# ---- R/dimoose.R ------------------------------------------------------------
#' A dichotomous key
#'
#' @description
#' An R6 object holding a dichotomous key as a table of the leads on every
#' path from the root to a terminal taxon. Usually created by
#' [importFishbase()] or [parseFishbase()]. See
#' <https://www.fishbase.se/keys/allkeys.php> for FishBase keys.
#'
#' @field desc Key title or description (read-only).
#' @field df Data frame with one row per lead (or per term, if terms were
#'   separated) per terminal taxon, with columns `Statement`, `Choice`,
#'   `Character`, `Taxon`, and `pSt`/`pCh` for the parent lead.
#' @field meta Key/value data frame of metadata (citation, image URLs, ...).
#' @field taxa Data frame of terminal taxa and their resolved names.
#' @field leads Data frame with one row per lead: `Statement`, `Choice`,
#'   `Character`, `Next` (next couplet, or `"-"` if terminal) and `Taxon`,
#'   plus optional `Prev`, `Image`, `ImageLink`, `TaxonUrl`, `Question`,
#'   `Feature`, `Test` and `Threshold`. Derived from `df` when the object
#'   was created without one.
#' @field features Data frame of features a machine can compute, one per
#'   row (see [featureTable()]), or `NULL` for keys meant only for people.
#' @export
dimoose <- R6::R6Class("dimoose",
  lock_objects = FALSE,
  lock_class = TRUE,
  portable = TRUE,
  class = TRUE,
  cloneable = TRUE,
  private = list(
    .desc = NA,
    .df = NULL,
    .meta = NULL,
    .taxa = NULL,
    .leads = NULL,
    .features = NULL
  ),
  active = list(
    desc = function(value) {
      if (missing(value)) {
        private$.desc
      } else {
        stop("`$desc` is read only", call. = FALSE)
      }
    },
    df = function(value) {
      if (missing(value)) {
        private$.df
      } else {
        stopifnot(is.data.frame(value), nrow(value) > 0)
        private$.df <- value
        self
      }
    },
    meta = function(value) {
      if (missing(value)) {
        private$.meta
      } else {
        stopifnot(is.data.frame(value), nrow(value) > 0)
        private$.meta <- value
        self
      }
    },
    taxa = function(value) {
      if (missing(value)) {
        private$.taxa
      } else {
        stopifnot(is.data.frame(value), nrow(value) > 0)
        private$.taxa <- value
        self
      }
    },
    leads = function(value) {
      if (missing(value)) {
        if (is.null(private$.leads)) leadsFromPaths(private$.df) else private$.leads
      } else {
        stopifnot(is.data.frame(value), nrow(value) > 0)
        private$.leads <- value
        self
      }
    },
    features = function(value) {
      if (missing(value)) {
        private$.features
      } else {
        stopifnot(is.null(value) || is.data.frame(value))
        private$.features <- value
        self
      }
    }
  ),
  public = list(
    #' @description Create a new dimoose object.
    #' @param df Data frame of leads (see the `df` field).
    #' @param desc Key title or description.
    #' @param meta Key/value metadata data frame.
    #' @param taxa Data frame of terminal taxa.
    #' @param leads Optional data frame of leads (see the `leads` field).
    #' @param features Optional data frame of machine-readable features (see
    #'   [featureTable()]).
    initialize = function(df, desc = NA, meta = NA, taxa = NA, leads = NULL, features = NULL) {
      private$.df <- df
      private$.desc <- desc
      private$.meta <- meta
      private$.taxa <- taxa
      private$.leads <- leads
      private$.features <- features
    },
    #' @description Print a short overview of the key.
    #' @param ... Unused.
    print = function(...) {
      s <- self$summary()
      cat("<dimoose key> ", if (is.na(s$title)) "(untitled)" else s$title, "\n", sep = "")
      cat(sprintf("  %d couplets, %d leads, %d taxa, up to %d steps deep%s\n",
        s$couplets, s$leads, s$taxa, s$depth,
        if (is.na(s$meanTaxonSteps)) "" else sprintf(" (%.1f on average)", s$meanTaxonSteps)))
      if (s$problems > 0) cat(sprintf("  %d problem(s): see $validate()\n", s$problems))
      invisible(self)
    },
    #' @description Counts describing the key and how quickly it reaches a
    #'   result (see [keyQuality()]).
    #' @param weights Optional named numeric vector of how common each taxon
    #'   is, as for [keyQuality()]; by default all taxa count the same.
    #' @return A one-row data frame: `title`, `couplets`, `leads`, `taxa`,
    #'   `depth` (longest path in steps), `problems` (see `validate()`),
    #'   `meanLeadSteps` and `meanTaxonSteps` (steps to a result, averaged
    #'   over terminal leads and over taxa), `expectedSteps` (averaged over
    #'   taxa by `weights`), `bound` (the expected steps of the best key
    #'   there could be to these taxa, with couplets no larger than this
    #'   key's largest) and `efficiency` (`bound / expectedSteps`, 1 for a
    #'   key that could not be shorter).
    summary = function(weights = NULL) {
      leads <- normalizeLeads(self$leads)
      check <- checkLeads(leads)
      quality <- keyQuality(self, weights)
      data.frame(
        title = if (length(private$.desc) == 1) as.character(private$.desc) else NA_character_,
        couplets = length(check$couplets),
        leads = nrow(leads),
        taxa = length(unique(leads$Taxon[leads$Next == "-" & nzchar(leads$Taxon)])),
        depth = quality$depth,
        problems = length(check$problems),
        meanLeadSteps = quality$meanLeadSteps,
        meanTaxonSteps = quality$meanTaxonSteps,
        expectedSteps = quality$expectedSteps,
        bound = quality$bound,
        efficiency = quality$efficiency,
        stringsAsFactors = FALSE
      )
    },
    #' @description Check the key: leads to missing couplets, terminal leads
    #'   without a taxon, couplets with fewer than two leads, couplets that
    #'   cannot be reached from the first one, and (for keys with features)
    #'   leads whose machine test is missing or inconsistent.
    #' @return A character vector of problems, invisibly if there are none.
    validate = function() {
      leads <- normalizeLeads(self$leads)
      problems <- c(checkLeads(leads)$problems, checkFeatures(leads, private$.features))
      if (length(problems)) problems else invisible(character())
    },
    #' @description Convert the key to a [data.tree::Node]: couplets are
    #'   internal nodes and taxa leaves; each child node carries the `lead`
    #'   label and the `character` text of the lead that leads to it. A
    #'   couplet reached from several leads is attached under the first.
    toDataTree = function() {
      leads <- normalizeLeads(self$leads)
      check <- checkLeads(leads)
      label <- leadLabels(leads)
      root <- data.tree::Node$new(check$root)
      nodes <- list()
      nodes[[check$root]] <- root
      queue <- check$root
      while (length(queue)) {
        cp <- queue[1]
        queue <- queue[-1]
        parent <- nodes[[cp]]
        for (i in which(leads$Statement == cp)) {
          nx <- leads$Next[i]
          if (nx == "-") {
            name <- if (nzchar(leads$Taxon[i])) leads$Taxon[i] else label[i]
            if (name %in% names(parent$children)) name <- paste0(name, " (", label[i], ")")
            parent$AddChild(dataTreeSafeName(name, parent), label = name, lead = label[i], character = leads$Character[i], taxon = TRUE)
          } else if (nx %in% check$couplets && is.null(nodes[[nx]])) {
            nodes[[nx]] <- parent$AddChild(dataTreeSafeName(nx, parent), label = nx, lead = label[i], character = leads$Character[i], taxon = FALSE)
            queue <- c(queue, nx)
          }
        }
      }
      root
    },
    #' @description Write the key's topology in Newick format, with couplets
    #'   as internal node labels and taxa as leaves (labels quoted when
    #'   needed). A couplet reached from several leads is placed under the
    #'   first.
    #' @return A single string ending in `;`.
    toNewick = function() {
      leads <- normalizeLeads(self$leads)
      check <- checkLeads(leads)
      quote <- function(x) {
        if (grepl("^[A-Za-z0-9_.*-]+$", x)) x else paste0("'", gsub("'", "''", x, fixed = TRUE), "'")
      }
      byCouplet <- split(seq_len(nrow(leads)), factor(leads$Statement, levels = check$couplets))
      placed <- new.env()
      newick <- function(cp) {
        assign(cp, TRUE, envir = placed)
        kids <- character()
        for (i in byCouplet[[cp]]) {
          nx <- leads$Next[i]
          if (nx == "-") {
            kids <- c(kids, quote(if (nzchar(leads$Taxon[i])) leads$Taxon[i] else leadLabels(leads[i, ])))
          } else if (nx %in% check$couplets && !exists(nx, envir = placed, inherits = FALSE)) {
            kids <- c(kids, newick(nx))
          }
        }
        paste0(if (length(kids)) paste0("(", paste(kids, collapse = ","), ")") else "", quote(cp))
      }
      paste0(newick(check$root), ";")
    }
  )
)


#' Raw FishBase key tables
#'
#' @description
#' An R6 object holding a FishBase key's description and its couplet table as
#' downloaded, before conversion to a [dimoose] object.
#'
#' @field desc Key title (read-only).
#' @field df The key's couplet table: one row per lead, with columns
#'   `Statement`, `Choice`, `Character`, `Next`, `Prev` and `Taxon`.
#' @export
rawhtml <- R6::R6Class("rawhtml",
  lock_objects = FALSE,
  lock_class = TRUE,
  portable = TRUE,
  class = TRUE,
  cloneable = TRUE,
  private = list(
    .desc = NA,
    .df = NULL,
    .meta = NULL
  ),
  active = list(
    desc = function(value) {
      if (missing(value)) {
        private$.desc
      } else {
        stop("`$desc` is read only", call. = FALSE)
      }
    },
    df = function(value) {
      if (missing(value)) {
        private$.df
      } else {
        stopifnot(is.data.frame(value), nrow(value) > 0)
        private$.df <- value
        self
      }
    }
  ),
  public = list(
    #' @description Print the description, table and metadata.
    #' @param ... Unused.
    print = function(...) {
      print(private$.desc)
      print(private$.df)
      print(private$.meta)
      invisible(self)
    },
    #' @description Download a FishBase key.
    #' @param keycode FishBase key code.
    #' @param fishbaseUrl Base URL of the FishBase mirror.
    #' @param separateTerms Ignored; kept for backward compatibility.
    initialize = function(keycode, fishbaseUrl = "https://www.fishbase.se/", separateTerms = TRUE) {
      pages <- fetchFishbasePages(keycode, fishbaseUrl)
      private$.desc <- parseFishbaseDescription(pages$description)$desc
      private$.df <- parseFishbaseKeyTable(pages$questions)
    }
  )
)

# Rebuild a lead table from the path table (`dimoose$df`): one row per lead,
# with Next taken from the leads whose parent is this lead.
leadsFromPaths <- function(df) {
  if (is.null(df) || nrow(df) == 0) {
    return(data.frame(
      Statement = character(), Choice = character(), Character = character(),
      Next = character(), Taxon = character(), stringsAsFactors = FALSE
    ))
  }
  leadKey <- paste(df$Statement, df$Choice, sep = "\r")
  parentKey <- paste(df$pSt, df$pCh, sep = "\r")
  keys <- unique(leadKey)
  rows <- lapply(keys, function(k) {
    here <- df[leadKey == k, , drop = FALSE]
    children <- unique(df$Statement[parentKey == k])
    terminal <- length(children) == 0
    data.frame(
      Statement = here$Statement[1],
      Choice = here$Choice[1],
      Character = paste(unique(here$Character), collapse = "; "),
      Next = if (terminal) "-" else children[1],
      Taxon = if (terminal) unique(here$Taxon)[1] else "",
      stringsAsFactors = FALSE
    )
  })
  out <- do.call(rbind, rows)
  ord <- order(suppressWarnings(as.numeric(out$Statement)), out$Statement, out$Choice)
  out <- out[ord, , drop = FALSE]
  rownames(out) <- NULL
  out
}

#' @export
summary.dimoose <- function(object, ...) {
  object$summary(...)
}

# ---- R/import.R ------------------------------------------------------------
#' Import a dichotomous key from FishBase
#'
#' Downloads a key from FishBase and converts it into a [dimoose] object. See
#' <https://www.fishbase.se/keys/allkeys.php> for the list of keys and their
#' key codes.
#'
#' @param keycode Numeric or character FishBase key code.
#' @param fishbaseUrl Base URL of the FishBase mirror, with a trailing slash.
#' @param separateTerms If `TRUE`, split each lead's character statement on
#'   `";"` into one row per term.
#' @param usePhyloService Taxonomic name resolution: `"GNA"` verifies terminal
#'   taxa with the Global Names verifier (`taxize::gna_verifier()`, requires
#'   the 'taxize' package); `"none"` skips resolution. `"GNR"` is accepted as
#'   an alias for `"GNA"`. `"TNRS"` is no longer available because
#'   `taxize::tnrs()` is defunct.
#' @param embedImages If `TRUE`, download the key's morphology images and store
#'   them base64-encoded in `meta`. Image URLs are always stored.
#' @return A [dimoose] object.
#' @seealso [parseFishbase()] to build a key from saved HTML pages.
#' @examples
#' \dontrun{
#' sharks <- importFishbase(1)
#' sharks$taxa
#' }
#' @export
importFishbase <- function(keycode,
                           fishbaseUrl = "https://www.fishbase.se/",
                           separateTerms = TRUE,
                           usePhyloService = c("GNA", "GNR", "none", "TNRS"),
                           embedImages = FALSE) {
  usePhyloService <- match.arg(usePhyloService)
  pages <- fetchFishbasePages(keycode, fishbaseUrl)
  parseFishbase(
    pages$description, pages$questions,
    separateTerms = separateTerms,
    usePhyloService = usePhyloService,
    embedImages = embedImages,
    pageUrl = pages$questionsUrl
  )
}

#' Build a dimoose object from FishBase key pages
#'
#' The offline half of [importFishbase()]: parses a FishBase key description
#' page and its questions (couplet) page, both already downloaded.
#'
#' @param description The description page (`keys/description.php`): an
#'   `xml_document`, a file path, or a string of HTML.
#' @param questions The questions page (`keys/questions.php`), in any of the
#'   same forms.
#' @inheritParams importFishbase
#' @param pageUrl URL of the questions page, used to resolve relative image
#'   links.
#' @return A [dimoose] object.
#' @examples
#' \dontrun{
#' parseFishbase("description.html", "questions.html", usePhyloService = "none")
#' }
#' @export
parseFishbase <- function(description, questions,
                          separateTerms = TRUE,
                          usePhyloService = c("GNA", "GNR", "none", "TNRS"),
                          embedImages = FALSE,
                          pageUrl = "https://www.fishbase.se/keys/questions.php") {
  usePhyloService <- match.arg(usePhyloService)
  descDoc <- asHtmlDocument(description)
  keyDoc <- asHtmlDocument(questions)

  info <- parseFishbaseDescription(descDoc)
  keytable <- parseFishbaseKeyTable(keyDoc, pageUrl = pageUrl)
  df <- keyPaths(keytable, separateTerms = separateTerms)

  leaves <- keytable[keytable$Next == "-", , drop = FALSE]
  taxa <- resolveTaxa(leaves$Taxon, service = usePhyloService)

  imageUrls <- fishbaseImageUrls(keyDoc, pageUrl)
  imageNames <- sub("\\.gif$", "", basename(imageUrls), ignore.case = TRUE)
  meta <- data.frame(
    key = c("citation", "transcription", paste0("image_url_", imageNames)),
    value = c(info$citation, info$transcription, imageUrls),
    stringsAsFactors = FALSE
  )
  if (isTRUE(embedImages) && length(imageUrls) > 0) {
    encoded <- vapply(imageUrls, downloadAndEncodeImage, character(1))
    keep <- !is.na(encoded)
    meta <- rbind(meta, data.frame(
      key = paste0("image_", imageNames[keep]),
      value = unname(encoded[keep]),
      stringsAsFactors = FALSE
    ))
  }

  dimoose$new(df, info$desc, meta, taxa, leads = keytable)
}

# ---- internals --------------------------------------------------------------

dimooseUserAgent <- function() {
  httr::user_agent("dimoose R package (https://github.com/leipzig/dimoose)")
}

asHtmlDocument <- function(x) {
  if (inherits(x, "xml_document")) {
    return(x)
  }
  xml2::read_html(x)
}

fetchFishbasePages <- function(keycode, fishbaseUrl) {
  descUrl <- paste0(fishbaseUrl, "keys/description.php?keycode=", keycode)
  descResponse <- httr::GET(descUrl, dimooseUserAgent(), httr::timeout(60))
  httr::stop_for_status(descResponse, task = "download the FishBase key description")

  # FishBase serves the couplets only in response to a form POST
  questionsUrl <- paste0(fishbaseUrl, "keys/questions.php")
  keyResponse <- httr::POST(questionsUrl,
    body = list(keycode = keycode), encode = "form",
    dimooseUserAgent(), httr::timeout(60)
  )
  httr::stop_for_status(keyResponse, task = "download the FishBase key couplets")

  list(
    description = httr::content(descResponse),
    questions = httr::content(keyResponse),
    questionsUrl = questionsUrl
  )
}

# Title, citation and transcription note from the first table of the
# description page, as plain strings.
parseFishbaseDescription <- function(doc) {
  tables <- rvest::html_nodes(doc, "table")
  if (length(tables) == 0) {
    stop("No table found in the FishBase key description page", call. = FALSE)
  }
  cells <- trimws(as.character(rvest::html_table(tables[[1]], header = FALSE)[[1]]))
  list(desc = cells[1], citation = cells[2], transcription = cells[3])
}

# One row per lead: Statement (couplet number), Choice (a/b/...), Character,
# Next (couplet it leads to, or "-" for a terminal lead), Prev, Taxon, plus
# absolute URLs from the lead's Link cell: Image (thumbnails, ";"-separated),
# ImageLink (full-size figures) and TaxonUrl (FishBase species list or key).
parseFishbaseKeyTable <- function(doc, pageUrl = "https://www.fishbase.se/keys/questions.php") {
  tables <- rvest::html_nodes(doc, "table")
  if (length(tables) == 0) {
    stop("No table found in the FishBase key page", call. = FALSE)
  }
  raw <- rvest::html_table(tables[[1]], header = FALSE, convert = FALSE)
  header <- which(trimws(raw[[1]]) == "Couplet")[1]
  if (is.na(header)) {
    stop("Could not find the 'Couplet' header row in the FishBase key table", call. = FALSE)
  }
  keep <- seq_len(nrow(raw)) > header
  body <- raw[keep, , drop = FALSE]
  names(body) <- trimws(unlist(raw[header, ], use.names = FALSE))

  required <- c("Couplet", "Character", "Next", "Prev", "Link")
  missing <- setdiff(required, names(body))
  if (length(missing) > 0) {
    stop("FishBase key table is missing column(s): ",
      paste(missing, collapse = ", "),
      call. = FALSE
    )
  }

  links <- linkCellUrls(tables[[1]], nrow(raw), match("Link", names(body)), pageUrl)

  couplet <- strsplit(trimws(body$Couplet), "\\s+")
  data.frame(
    Statement = vapply(couplet, function(x) x[1], character(1)),
    Choice = vapply(couplet, function(x) if (length(x) >= 2) x[2] else "", character(1)),
    Character = trimws(body$Character),
    Next = trimws(body$Next),
    Prev = gsub("[()]", "", trimws(body$Prev)),
    Taxon = cleanTaxon(body$Link),
    Image = links$Image[keep],
    ImageLink = links$ImageLink[keep],
    TaxonUrl = links$TaxonUrl[keep],
    stringsAsFactors = FALSE
  )
}

# URLs found in the Link cell of each table row. Rows whose <tr> count does
# not match the parsed table (unexpected markup) get empty strings.
linkCellUrls <- function(table, nrows, linkCol, pageUrl) {
  empty <- rep("", nrows)
  out <- list(Image = empty, ImageLink = empty, TaxonUrl = empty)
  rows <- rvest::html_nodes(table, "tr")
  if (length(rows) != nrows || is.na(linkCol)) {
    return(out)
  }
  absolute <- function(x) {
    x <- x[!is.na(x) & nzchar(x)]
    if (length(x) == 0) character() else unique(xml2::url_absolute(x, pageUrl))
  }
  for (i in seq_len(nrows)) {
    cells <- rvest::html_nodes(rows[[i]], "td")
    if (length(cells) < linkCol) next
    cell <- cells[[linkCol]]
    img <- absolute(rvest::html_attr(rvest::html_nodes(cell, "img"), "src"))
    href <- absolute(rvest::html_attr(rvest::html_nodes(cell, "a"), "href"))
    isFigure <- grepl("\\.(gif|jpe?g|png)$", href, ignore.case = TRUE)
    out$Image[i] <- paste(img, collapse = ";")
    out$ImageLink[i] <- paste(href[isFigure], collapse = ";")
    out$TaxonUrl[i] <- if (any(!isFigure)) href[!isFigure][1] else ""
  }
  out
}

# "Echinorhinidae, Key" -> "Echinorhinidae"
cleanTaxon <- function(x) {
  x <- trimws(ifelse(is.na(x), "", x))
  x <- sub(",?\\s*Key$", "", x)
  trimws(gsub(",", "", x))
}

# For every terminal lead, walk back to the root and emit the leads on the
# path. Columns: Statement, Choice, Character, Taxon, pSt, pCh, where pSt/pCh
# identify the lead that points at this lead's couplet ("" at the root).
# A couplet reached from more than one lead contributes one path per parent.
keyPaths <- function(keytable, separateTerms = TRUE) {
  n <- nrow(keytable)
  empty <- data.frame(
    Statement = character(), Choice = character(), Character = character(),
    Taxon = character(), pSt = character(), pCh = character(),
    stringsAsFactors = FALSE
  )
  if (n == 0) return(empty)
  stmt <- as.character(keytable$Statement)
  nxt <- as.character(keytable$Next)
  parentsOf <- split(seq_len(n), factor(nxt, levels = unique(stmt)))

  # Every path from the root to lead i, as vectors of lead indices. Walks up
  # with an explicit stack, so deep keys do not exhaust R's call stack.
  pathsTo <- function(i) {
    done <- list()
    stack <- list(i)
    while (length(stack)) {
      path <- stack[[length(stack)]]; stack[[length(stack)]] <- NULL
      parents <- parentsOf[[stmt[path[1]]]]
      if (length(parents) == 0) { done[[length(done) + 1]] <- path; next }
      for (p in rev(parents)) {
        if (stmt[p] %in% stmt[path]) {
          stop("Cycle in key: couplet ", stmt[p], " is reachable from itself", call. = FALSE)
        }
        stack[[length(stack) + 1]] <- c(p, path)
      }
    }
    done
  }

  leaves <- which(nxt == "-")
  paths <- list()
  taxa <- character()
  for (leaf in leaves) {
    found <- pathsTo(leaf)
    paths <- c(paths, found)
    taxa <- c(taxa, rep(keytable$Taxon[leaf], length(found)))
  }
  if (length(paths) == 0) return(empty)

  lead <- unlist(paths)
  prev <- unlist(lapply(paths, function(path) c(NA, path[-length(path)])))
  taxon <- rep(taxa, lengths(paths))
  terms <- as.list(as.character(keytable$Character))
  if (separateTerms) {
    terms <- lapply(strsplit(as.character(keytable$Character), ";", fixed = TRUE), trimws)
    terms[lengths(terms) == 0] <- ""
  }
  reps <- lengths(terms)[lead]
  out <- data.frame(
    Statement = rep(stmt[lead], reps),
    Choice = rep(as.character(keytable$Choice)[lead], reps),
    Character = unlist(terms[lead], use.names = FALSE),
    Taxon = rep(taxon, reps),
    pSt = rep(ifelse(is.na(prev), "", stmt[prev]), reps),
    pCh = rep(ifelse(is.na(prev), "", as.character(keytable$Choice)[prev]), reps),
    stringsAsFactors = FALSE
  )
  rownames(out) <- NULL
  out
}

# One row per unique submitted name. matched_name falls back to the submitted
# name when resolution is skipped, unavailable, or finds no match.
resolveTaxa <- function(taxa, service = c("GNA", "GNR", "none", "TNRS")) {
  service <- match.arg(service)
  if (service == "TNRS") {
    stop("usePhyloService = \"TNRS\" is no longer available: taxize::tnrs() is defunct ",
      "because the Phylotastic TNRS service shut down. Use \"GNA\" or \"none\".",
      call. = FALSE
    )
  }
  taxa <- unique(taxa[!is.na(taxa) & nzchar(taxa)])
  out <- data.frame(
    submitted_name = taxa,
    matched_name = taxa,
    current_name = rep(NA_character_, length(taxa)),
    match_type = rep(NA_character_, length(taxa)),
    data_source = rep(NA_character_, length(taxa)),
    stringsAsFactors = FALSE
  )
  if (service == "none" || length(taxa) == 0) {
    return(out)
  }
  if (!requireNamespace("taxize", quietly = TRUE)) {
    warning("Package 'taxize' is not installed; skipping taxonomic name resolution.",
      call. = FALSE
    )
    return(out)
  }
  verified <- tryCatch(
    taxize::gna_verifier(taxa),
    error = function(e) {
      warning("Taxonomic name resolution failed: ", conditionMessage(e), call. = FALSE)
      NULL
    }
  )
  if (is.null(verified) || nrow(verified) == 0) {
    return(out)
  }
  idx <- match(out$submitted_name, verified$submittedName)
  canonical <- as.character(verified$matchedCanonicalSimple[idx])
  found <- !is.na(canonical) & nzchar(canonical)
  out$matched_name[found] <- canonical[found]
  out$current_name <- as.character(verified$currentCanonicalSimple[idx])
  out$match_type <- as.character(verified$matchType[idx])
  out$data_source <- as.character(verified$dataSourceTitleShort[idx])
  out
}

fishbaseImageUrls <- function(doc, pageUrl) {
  src <- rvest::html_attr(rvest::html_nodes(doc, "img"), "src")
  src <- unique(src[!is.na(src) & grepl("morphpic/.*\\.gif$", src, ignore.case = TRUE)])
  xml2::url_absolute(src, pageUrl)
}

# Base64-encoded image, or NA on failure.
downloadAndEncodeImage <- function(url) {
  tryCatch(
    {
      response <- httr::GET(url, dimooseUserAgent(), httr::timeout(30))
      if (httr::status_code(response) != 200) {
        warning("Failed to download image: ", url, call. = FALSE)
        return(NA_character_)
      }
      base64enc::base64encode(httr::content(response, as = "raw"))
    },
    error = function(e) {
      warning("Failed to download image: ", url, call. = FALSE)
      NA_character_
    }
  )
}

# ---- R/export.R ------------------------------------------------------------
#' Export an interactive dichotomous key
#'
#' Writes a dimoose key as a single self-contained HTML page. With JavaScript
#' on, the page steps through the key one couplet at a time, keeps a trail of
#' the choices made (each one clickable to go back to it) and supports the
#' browser's Back button. Without JavaScript, the same page is the full key
#' with every lead hyperlinked to its next couplet or taxon. Each taxon gets
#' a result section listing the characters on its path, and a map of the
#' key shows where the user is (see `map`).
#'
#' The key is checked first: leads pointing at missing couplets, terminal
#' leads without a taxon, couplets with fewer than two leads and couplets
#' that cannot be reached from the first one are reported as warnings and
#' marked in the page.
#'
#' @section Not sure:
#' Every couplet has an "I'm not sure" button (keys `u` or `?`). It follows
#' all leads of the couplet at once. The page then asks the questions of one
#' branch at a time, lists the branches still open (click one to answer it
#' next), and counts and marks on the map the taxa possible in any of them.
#' Each answer narrows its own branch. If the reader stays unsure to the end,
#' the page lists every result that is left. Back undoes one step at a time.
#' The address of the page records the open branches (`#open=c-3,c-9`), so a
#' reload or a shared link returns to the same place; the trail of choices
#' comes back too when the browser restores the page's history entry.
#'
#' @section Picking characters in any order:
#' With `matrix`, the page gains a second way in: a list of the characters of
#' the matrix, to answer in any order. Picking a state removes the taxa that
#' do not have it. A taxon with several states (`"a/b"`) fits any of them, and
#' a taxon whose state is unknown (`NA`) fits all. The characters that still
#' separate the remaining taxa are listed first: cheapest first when
#' `characters` gives a `Cost`, then those that leave the fewest taxa on
#' average. Taxa of the matrix are matched to the key's taxa by name (ignoring
#' case), so the remaining taxa link to their result sections and show on the
#' map, and the page offers to continue step by step from the couplet they all
#' share. Without JavaScript the matrix is a plain table. The two ways are
#' otherwise independent: answers given step by step do not filter the
#' character list. With `key = NULL` the page is the character list alone.
#'
#' @section Offline use:
#' The page itself needs no connection once it is open, but a browser will not
#' reopen a page it cannot fetch. `offline = TRUE` writes four files next to
#' `file`, named after it: a web app manifest (`<name>.webmanifest`), a
#' service worker (`<name>-sw.js`) and two icons (`<name>-icon-192.png`,
#' `<name>-icon-512.png`; the package logo if the rsvg package is installed,
#' otherwise a simple drawn icon). The worker stores the page, the manifest,
#' the icons and the figures the page loads from other sites, so that the
#' page can be installed on a phone ("Add to Home Screen") and opened without
#' signal. Upload all five files to the same folder. Limits:
#'
#' * Browsers run service workers only on `https://` or `http://localhost`. A
#'   page opened from disk (`file://`) works as before but is not installed
#'   and stores nothing.
#' * The page must be opened once with a connection before it works without.
#' * Figures on other sites are fetched when the worker installs and again
#'   when first shown; any that fail are skipped. A site that does not allow
#'   cross-origin requests gives an opaque copy, which browsers count as
#'   several megabytes each against the storage they allow, so a key with
#'   many such figures may not store them all. Figures embedded in the key
#'   (see [imageMeta()]) are part of the page and always available. Full-size
#'   figures and taxon pages that open in a new tab are not stored.
#' * The worker only controls the page it was written for (its scope is the
#'   page's own address), so several keys can share a folder. Serve the page
#'   under its file name; a server that drops the `.html` from addresses puts
#'   the page outside the worker's scope.
#'
#' @section Identifying from a photo:
#' `photoModel` adds an "Identify from a photo" button. The reader takes or
#' picks a photo; the page loads the model and
#' [onnxruntime-web](https://onnxruntime.ai/docs/tutorials/web/) (the program
#' that runs it, version 1.31.1, about 15 MB, from the jsDelivr CDN unless
#' `photoRuntime` says otherwise), prepares the picture as the model's
#' `model.json` says, runs the image encoder in the browser and compares the
#' result with the text embeddings of the key's taxa. The photo never leaves
#' the reader's device. The page then marks the likely taxa on the map, lists
#' the five best with their scores, each linked to its result, and offers to
#' narrow the key to them: the leads that reach none of them are greyed and
#' the count of remaining taxa follows, but every lead still works. The key
#' stays the authority; the photo is a hint.
#'
#' `photoModel` is a folder written by [exportBrowserModel()] for the same
#' key, or the web address of one. The model is not put into the page. A
#' folder is copied next to `file` as `<name>_model/` (so `file` is needed);
#' upload it with the page. A web address is used as it is; a model on
#' another site must allow cross-origin requests. What to expect:
#'
#' * Nothing is downloaded until the reader has chosen a photo, been told the
#'   size and agreed. An int8 BioCLIP encoder is 90 MB; with the runtime that
#'   is about 105 MB on first use. The page shows the progress.
#' * With `offline = TRUE` the service worker keeps the model and the runtime
#'   once they have been fetched, so photos can be identified without a
#'   connection afterwards. That is the same 105 MB or so of storage on the
#'   reader's device, and the first use still needs a connection.
#' * It needs a browser with WebAssembly, and memory: several times the size
#'   of the encoder while it loads. If the browser cannot run the model, runs
#'   out of memory or cannot fetch it, the page says so and the key works as
#'   before. A page opened from disk (`file://`) cannot load the model.
#' * Only the WebAssembly backend is used, on one thread unless the page is
#'   served cross-origin isolated. That suits int8 encoders, which WebGPU
#'   cannot run.
#' * The scores compare the key's taxa with each other and add up to 100%,
#'   so a photo of something that is not in the key still gets a confident
#'   best match. If `model.json` has a `min_similarity`, a best match whose
#'   cosine similarity is under it is shown as "Not much like any taxon of
#'   this key" without a percentage.
#'
#' @section Notes on leads:
#' A `Note` column in the key's leads, as [pruneKey()] writes when it
#' collapses a couplet (the character of the couplet that is no longer asked),
#' is shown under its lead as "Also:" and in the path of each result. A
#' `pruned_note` in the key's meta (the same for a collapsed first couplet) is
#' shown under the title.
#'
#' @section Hook for other scripts:
#' The page defines `window.dimoose` so that another script, for example one
#' that identifies a photo in the browser, can work with the page without
#' knowing how it is built:
#'
#' * `dimoose.taxa`: array of `{ id, name }`, one per result.
#' * `dimoose.highlight(scores, opts)`: `scores` is an object mapping taxon
#'   names or ids to numbers, or an array of `{ taxon, score }`; `null`
#'   clears. Marks those taxa on the map and in every list of candidates and
#'   lists the five best above the key, headed by `opts.label` (default
#'   "Suggested"). Scores all within 0 to 1 are shown as percentages. Returns
#'   the ids it marked, best first.
#' * `dimoose.goToTaxon(nameOrId)`: shows that result; `false` if unknown.
#' * `dimoose.narrow(namesOrIds)`: narrows the key to these taxa (see
#'   'Identifying from a photo'); `null` undoes it. Returns the ids kept.
#' * `dimoose.state()`: `{ shown, open, remaining, picks, narrowed }`, the
#'   section shown, the open branches, the ids of the taxa still possible, the
#'   states picked in the character list and the ids the key is narrowed to
#'   (or `null`).
#' * `dimoose.photo` (only with `photoModel`): `identify(file)`, a promise of
#'   the ranked taxa, and the pure steps `preprocess()` and `score()`.
#' * `dimoose.onChange(fn)`: calls `fn(state)` after every step.
#'
#' @param key A [dimoose] object, e.g. from [importFishbase()]. May be `NULL`
#'   if `matrix` is given.
#' @param file Path of the HTML file to write. If `NULL`, the HTML is returned
#'   as a string instead.
#' @param displayLinks If `TRUE`, show the couplet numbers each lead leads to
#'   and comes from, as in a printed key. If `FALSE`, hide them. Leads stay
#'   clickable either way.
#' @param order Deprecated and ignored. Couplets are always exported in the
#'   key's own order. `"parsimony"` was never implemented; to ask the
#'   questions that are easiest to observe first, build the key with
#'   [keyFromMatrix()] and give the characters a `Cost`.
#' @param title Page title. Defaults to the key's description.
#' @param staticPaths If `TRUE`, write each taxon's path through the key into
#'   the page, so it shows without JavaScript. If `FALSE`, the page builds
#'   the path in the browser when a result is shown, which keeps large keys
#'   (such as [phylotreeKey()] on the whole tree) much smaller. The default
#'   is `TRUE` for keys with up to 1,000 taxa.
#' @param map If `TRUE`, include a map of the key: the whole key drawn as a
#'   tree, marking the current couplet, the path taken so far and the
#'   branches (and number of taxa) still possible. It sits beside the key on
#'   wide screens and behind a Map button on phones.
#' @param matrix Optional character matrix: a data frame with one row per
#'   taxon, the taxon's name in column `taxon` and one column per character.
#'   Cells are states; several states of one taxon are separated by `"/"`;
#'   `NA` is unknown or inapplicable. See 'Picking characters in any order'.
#' @param characters Optional data frame describing the characters of
#'   `matrix`: column `Character` (a column name of `matrix`) and any of
#'   `Cost` (lower is easier to observe), `Season` (when it can be observed)
#'   and `Needs` (e.g. `"hand lens"`).
#' @param taxon Name of the column of `matrix` that holds the taxon names.
#' @param offline If `TRUE`, also write a web app manifest, a service worker
#'   and icons next to `file`, so that the page can be installed and opened
#'   without a connection. Needs `file`. See 'Offline use'.
#' @param photoModel Optional: a folder written by [exportBrowserModel()] for
#'   this key, or the web address (`https://...`) of one. Adds "Identify from
#'   a photo" to the page. See 'Identifying from a photo'.
#' @param photoRuntime Optional web address of a folder holding the `dist`
#'   files of onnxruntime-web (`ort.wasm.min.js`, `ort-wasm-simd-threaded.mjs`
#'   and `.wasm`), to serve them yourself instead of loading them from
#'   jsDelivr. Relative addresses are relative to the page.
#' @return The path to `file`, invisibly, or the HTML as a character string if
#'   `file` is `NULL`. With `offline = TRUE` or a `photoModel` folder the
#'   paths of the other files written are in attribute `"files"`.
#' @seealso [keyFromMatrix()] to build a key from a character matrix.
#' @examples
#' leads <- data.frame(
#'   Statement = c("1", "1", "2", "2"), Choice = c("a", "b", "a", "b"),
#'   Character = c("Wings present", "Wings absent", "Two wings", "Four wings"),
#'   Next = c("2", "-", "-", "-"), Taxon = c("", "Silverfish", "Fly", "Bee")
#' )
#' key <- keyFromLeads(leads, "A tiny key")
#' html <- exportWizard(key)
#' substr(html, 1, 15)
#'
#' # With a character matrix the reader can also pick characters in any order
#' insects <- data.frame(
#'   Taxon = c("Silverfish", "Fly", "Bee", "Ant"),
#'   Wings = c("absent", "present", "present", "present/absent"),
#'   Sting = c("absent", "absent", "present", NA)
#' )
#' characters <- data.frame(Character = c("Wings", "Sting"), Cost = c(1, 3),
#'                          Needs = c("", "hand lens"))
#' html <- exportWizard(key, matrix = insects, characters = characters)
#'
#' # A matrix alone makes a page with only the character list
#' html <- exportWizard(NULL, matrix = insects, title = "Four insects")
#'
#' # An installable copy that opens without a connection once it is served
#' # over https: the page, a manifest, a service worker and two icons
#' dir <- tempfile("key")
#' dir.create(dir)
#' out <- exportWizard(key, file.path(dir, "insects.html"), offline = TRUE)
#' list.files(dir)
#' unlink(dir, recursive = TRUE)
#' @export
exportWizard <- function(key = NULL, file = NULL, displayLinks = TRUE,
                         order = "original", title = NULL,
                         map = TRUE, staticPaths = NULL,
                         matrix = NULL, characters = NULL, taxon = "Taxon",
                         offline = FALSE, photoModel = NULL, photoRuntime = NULL) {
  order <- match.arg(order, c("original", "parsimony"))
  if (order == "parsimony") {
    warning("`order` is deprecated and ignored: exportWizard() keeps the key's own order. ",
            "To ask the easiest questions first, build the key with ",
            "keyFromMatrix(characters = ) and give the characters a Cost.", call. = FALSE)
  }
  if (is.null(key)) {
    if (is.null(matrix)) stop("Give a `key`, a `matrix`, or both", call. = FALSE)
    leads <- normalizeLeads(data.frame(Statement = character(), stringsAsFactors = FALSE))
    check <- list(root = NA_character_, couplets = character(), missingTarget = logical(),
                  unreachable = character(), problems = character())
    key <- list(desc = NA, meta = NULL, taxa = NULL, features = NULL)
  } else {
    if (!inherits(key, "dimoose")) {
      stop("`key` must be a dimoose object", call. = FALSE)
    }
    leads <- normalizeLeads(key$leads)
    if (nrow(leads) == 0) {
      stop("This key has no leads to export", call. = FALSE)
    }
    check <- checkLeads(leads)
    for (w in check$problems) warning(w, call. = FALSE)
  }
  hasKey <- nrow(leads) > 0
  mx <- if (is.null(matrix)) NULL else wizMatrix(matrix, characters, taxon)
  if (is.null(mx) && !is.null(characters)) {
    warning("`characters` describes the columns of `matrix` and is ignored without one", call. = FALSE)
  }

  if (is.null(title)) {
    title <- if (length(key$desc) == 1 && !is.na(key$desc)) key$desc else if (hasKey) "Dichotomous key" else "Multi-access key"
  }
  nodeLabel <- metaValue(key$meta, "node_label")
  if (is.na(nodeLabel) || !nzchar(nodeLabel)) nodeLabel <- "Couplet"
  if (is.null(staticPaths)) {
    staticPaths <- length(unique(leads$Taxon[leads$Next == "-" & nzchar(leads$Taxon)])) <= 1000
  }
  images <- embeddedImages(key$meta)

  if (isTRUE(offline) && is.null(file)) {
    warning("offline = TRUE needs `file`: the manifest, service worker and icons are written next to it. ",
            "Returning the page alone.", call. = FALSE)
    offline <- FALSE
  }
  side <- if (isTRUE(offline)) wizOfflineNames(file) else NULL
  photo <- if (is.null(photoModel)) NULL else wizPhotoModel(photoModel, file, photoRuntime, leads)
  if (is.null(photo) && !is.null(photoRuntime)) {
    warning("`photoRuntime` is only used with `photoModel` and is ignored", call. = FALSE)
  }

  html <- renderWizard(leads, check,
    nodeLabel = nodeLabel,
    staticPaths = isTRUE(staticPaths),
    title = title,
    citation = metaValue(key$meta, "citation"),
    taxa = key$taxa,
    images = images,
    displayLinks = displayLinks,
    map = map,
    features = key$features,
    matrix = mx,
    offline = side,
    photo = photo,
    note = metaValue(key$meta, "pruned_note")
  )
  if (is.null(file)) {
    if (!is.null(photo)) wizPhotoMessage(photo, FALSE)
    return(html)
  }
  wizWriteText(html, file)
  written <- character()
  if (!is.null(side)) {
    written <- wizWriteOffline(side, html, title, wizExternalImages(leads, images),
                               keep = if (is.null(photo)) character() else photo$keep,
                               stamp = if (is.null(photo)) "" else photo$stamp)
  }
  if (!is.null(photo)) {
    written <- c(written, wizCopyPhotoModel(photo))
    wizPhotoMessage(photo, isTRUE(offline))
  }
  if (length(written)) attr(file, "files") <- written
  invisible(file)
}

# ---- identify from a photo -------------------------------------------------------

# onnxruntime-web, the program that runs the image encoder in the page. The
# version is pinned: the page loads these three files of it.
wizOrt <- list(
  version = "1.31.1",
  files = c("ort.wasm.min.js", "ort-wasm-simd-threaded.mjs", "ort-wasm-simd-threaded.wasm"),
  bytes = 53796 + 24738 + 14848852
)
wizOrtUrl <- function() sprintf("https://cdn.jsdelivr.net/npm/onnxruntime-web@%s/dist/", wizOrt$version)

# Checks `photoModel` (a folder written by exportBrowserModel() or the web
# address of one). Returns what the page and the copy need: `url` (the
# address of the folder as the page sees it), `runtime`, `runtimeBytes`
# (known for the pinned runtime only), `from`/`to`/`files` for a folder to
# copy, `bytes` of the model when known, and `keep`, the addresses
# (the model and the runtime) that the service worker should keep once
# fetched, with `stamp`, a fingerprint of the model. NULL (with a warning) when a
# folder is given but there is no `file` to copy it next to.
wizPhotoModel <- function(photoModel, file, runtime = NULL, leads = NULL) {
  if (!is.character(photoModel) || length(photoModel) != 1 || is.na(photoModel) || !nzchar(photoModel)) {
    stop("`photoModel` must be one folder written by exportBrowserModel(), or the web address of one", call. = FALSE)
  }
  folderUrl <- function(x) paste0(sub("/+$", "", x), "/")
  if (is.null(runtime)) {
    runtime <- wizOrtUrl()
    runtimeBytes <- wizOrt$bytes
  } else {
    if (!is.character(runtime) || length(runtime) != 1 || is.na(runtime) || !nzchar(runtime)) {
      stop("`photoRuntime` must be the web address of a folder with the files of onnxruntime-web", call. = FALSE)
    }
    runtime <- folderUrl(runtime)
    runtimeBytes <- NA_real_
  }
  out <- list(runtime = runtime, runtimeBytes = runtimeBytes, bytes = NA_real_, keep = runtime, stamp = "")
  if (grepl("^https?://", photoModel)) {
    out$url <- folderUrl(sub("model\\.json$", "", photoModel))
    out$keep <- c(out$keep, out$url)
    return(out)
  }
  dir <- if (!dir.exists(photoModel) && basename(photoModel) == "model.json") dirname(photoModel) else photoModel
  manifest <- file.path(dir, "model.json")
  if (!dir.exists(dir) || !file.exists(manifest)) {
    stop("`photoModel` must be a folder written by exportBrowserModel() (with a model.json), or a web address: ",
         photoModel, call. = FALSE)
  }
  text <- paste(readLines(manifest, warn = FALSE, encoding = "UTF-8"), collapse = "\n")
  if (!grepl("dimoose-browser-model", text, fixed = TRUE)) {
    stop(manifest, " is not a model written by exportBrowserModel()", call. = FALSE)
  }
  files <- c("model.json", list.files(dir, pattern = "\\.(bin|onnx)$"))
  if (requireNamespace("jsonlite", quietly = TRUE)) {
    m <- tryCatch(jsonlite::fromJSON(text, simplifyVector = FALSE), error = function(e) NULL)
    if (is.null(m)) stop(manifest, " cannot be read as JSON", call. = FALSE)
    named <- c(m$text_embeddings$file, m$image_encoder$file)
    missing <- named[!file.exists(file.path(dir, named))]
    if (length(missing)) stop("`photoModel` lacks ", paste(missing, collapse = ", "), ", which its model.json names", call. = FALSE)
    files <- c("model.json", named)
    if (!length(m$image_encoder$file) && !length(m$image_encoder$url)) {
      stop(manifest, " names no image encoder (neither a file nor a web address)", call. = FALSE)
    }
    if (length(m$image_encoder$url)) out$keep <- c(out$keep, m$image_encoder$url)
    if (length(m$image_encoder$bytes)) out$bytes <- as.numeric(m$image_encoder$bytes)
    if (!is.null(leads)) {
      labels <- vapply(m$labels, function(l) as.character(l$taxon), "")
      taxa <- unique(leads$Taxon[leads$Next == "-" & nzchar(leads$Taxon)])
      if (length(taxa) && !any(labels %in% taxa)) {
        warning("`photoModel` was made for another key: none of its ", length(labels),
                " labels is a result of this one, so a photo will highlight nothing. ",
                "Make it with exportBrowserModel() from this key.", call. = FALSE)
      } else if (length(setdiff(taxa, labels))) {
        message(length(setdiff(taxa, labels)), " of ", length(taxa), " results of the key are not in `photoModel` and cannot be suggested from a photo: ",
                paste(utils::head(setdiff(taxa, labels), 5), collapse = ", "), if (length(setdiff(taxa, labels)) > 5) ", ..." else "")
      }
    }
  }
  if (is.null(file)) {
    warning("A `photoModel` folder is copied next to `file`, so it needs `file` (or give a web address). ",
            "Returning the page without photo identification.", call. = FALSE)
    return(NULL)
  }
  if (is.na(out$bytes)) out$bytes <- sum(file.size(file.path(dir, files[grepl("\\.onnx$", files)])))
  folder <- paste0(sub("\\.[^.]*$", "", basename(file)), "_model")
  out$url <- paste0(utils::URLencode(folder, reserved = TRUE), "/")
  out$keep <- c(out$keep, out$url)
  # a model made again gets a new store on the reader's device
  out$stamp <- wizHash(paste(text, paste(file.size(file.path(dir, files)), collapse = " ")))
  out$from <- dir
  out$to <- file.path(dirname(file), folder)
  out$files <- unique(files)
  out
}

# Copies the model next to the page; files already there with the same size
# and no older than the source are left alone (the encoder is large).
wizCopyPhotoModel <- function(photo) {
  if (is.null(photo$from)) return(character())
  dir.create(photo$to, showWarnings = FALSE, recursive = TRUE)
  from <- file.path(photo$from, photo$files)
  to <- file.path(photo$to, photo$files)
  same <- normalizePath(from) == normalizePath(to, mustWork = FALSE)
  fresh <- file.exists(to) & file.size(to) == file.size(from) & file.mtime(to) >= file.mtime(from)
  todo <- !same & (is.na(fresh) | !fresh)
  ok <- file.copy(from[todo], to[todo], overwrite = TRUE, copy.date = TRUE)
  if (!all(ok)) stop("Could not copy the model to ", photo$to, call. = FALSE)
  to
}

wizPhotoMessage <- function(photo, offline) {
  mb <- function(x) paste(format(round(x / 1e6), big.mark = ","), "MB")
  model <- if (is.na(photo$bytes)) "the model" else paste0("the model (", mb(photo$bytes), ")")
  runtime <- if (is.na(photo$runtimeBytes)) "onnxruntime-web" else paste0("onnxruntime-web ", wizOrt$version, " (", mb(photo$runtimeBytes), ")")
  total <- photo$bytes + photo$runtimeBytes
  message(
    if (!is.null(photo$to)) paste0("The model was copied to ", photo$to, ": upload that folder with the page. "),
    "The first time a reader identifies a photo, the page downloads ", model, " and ", runtime,
    if (!is.na(total)) paste0(", ", mb(total), " in all"), ", after asking.",
    if (offline) paste0(" With offline = TRUE the service worker then keeps them",
                        if (!is.na(total)) paste0(" (", mb(total), " of storage on the reader's device)"),
                        ", so photos can be identified without a connection afterwards.")
  )
}

# Write bytes so UTF-8 text survives non-UTF-8 locales
wizWriteText <- function(text, file) {
  con <- file(file, open = "wb")
  on.exit(close(con))
  writeBin(charToRaw(enc2utf8(text)), con)
  invisible(file)
}

# ---- character matrix --------------------------------------------------------

# Checks a character matrix and its optional character table. Returns
# list(taxa, characters, cells, cost, season, needs): `cells` is a character
# matrix (taxa x characters) of trimmed state strings, NA where unknown;
# characters are ordered cheapest first when costs are given.
wizMatrix <- function(matrix, characters = NULL, taxon = "Taxon") {
  if (!is.data.frame(matrix)) stop("`matrix` must be a data frame with one row per taxon", call. = FALSE)
  if (!is.character(taxon) || length(taxon) != 1 || !taxon %in% names(matrix)) {
    stop("`taxon` must name the column of `matrix` that holds the taxon names", call. = FALSE)
  }
  name <- trimws(as.character(matrix[[taxon]]))
  if (length(name) == 0) stop("`matrix` has no rows", call. = FALSE)
  if (anyNA(name) || any(!nzchar(name))) stop("`matrix` has rows with no taxon name", call. = FALSE)
  if (anyDuplicated(name)) {
    stop("`matrix` lists a taxon more than once: ", paste(unique(name[duplicated(name)]), collapse = ", "),
         ". Give a variable taxon one row, with its states separated by \"/\".", call. = FALSE)
  }
  chars <- setdiff(names(matrix), taxon)
  if (length(chars) == 0) stop("`matrix` has no character columns", call. = FALSE)
  cells <- vapply(chars, function(ch) {
    x <- trimws(as.character(matrix[[ch]]))
    x[!is.na(x) & !nzchar(gsub("[/[:space:]]", "", x))] <- NA
    x
  }, character(length(name)))
  cells <- base::matrix(cells, nrow = length(name), dimnames = list(name, chars))

  cost <- rep(NA_real_, length(chars))
  season <- needs <- rep("", length(chars))
  if (!is.null(characters)) {
    if (!is.data.frame(characters) || !"Character" %in% names(characters)) {
      stop("`characters` must be a data frame with a column `Character`", call. = FALSE)
    }
    row <- match(chars, trimws(as.character(characters$Character)))
    text <- function(col) {
      if (is.null(characters[[col]])) return(rep("", length(chars)))
      x <- trimws(as.character(characters[[col]])[row])
      x[is.na(x)] <- ""
      x
    }
    if (!is.null(characters$Cost)) cost <- suppressWarnings(as.numeric(characters$Cost))[row]
    season <- text("Season")
    needs <- text("Needs")
  }
  o <- order(cost, na.last = TRUE)   # stable: matrix order among equal costs
  list(taxa = name, characters = chars[o], cells = cells[, o, drop = FALSE],
       cost = cost[o], season = season[o], needs = needs[o])
}

# The matrix as a section of the page: a plain table, which the page script
# reads and turns into the list of characters to pick from. `ids` gives the
# id of every taxon (the key's result section, or its own).
wizMatrixHtml <- function(mx, ids, linked) {
  note <- function(j) {
    bits <- c(if (nzchar(mx$needs[j])) paste("needs", mx$needs[j]), if (nzchar(mx$season[j])) mx$season[j])
    if (length(bits)) sprintf("<small>%s</small>", htmlEscape(paste(bits, collapse = " \u00b7 "))) else ""
  }
  head <- vapply(seq_along(mx$characters), function(j) {
    sprintf("<th scope=\"col\" data-char=\"%s\"%s%s%s>%s%s</th>",
      htmlEscape(mx$characters[j]),
      if (is.na(mx$cost[j])) "" else sprintf(" data-cost=\"%s\"", format(mx$cost[j], scientific = FALSE, trim = TRUE)),
      if (nzchar(mx$season[j])) sprintf(" data-season=\"%s\"", htmlEscape(mx$season[j])) else "",
      if (nzchar(mx$needs[j])) sprintf(" data-needs=\"%s\"", htmlEscape(mx$needs[j])) else "",
      htmlEscape(mx$characters[j]), note(j))
  }, character(1))
  rows <- vapply(seq_along(mx$taxa), function(i) {
    x <- mx$cells[i, ]
    cells <- ifelse(is.na(x), "<td data-na>?</td>", paste0("<td>", htmlEscape(x), "</td>"))
    name <- htmlEscape(mx$taxa[i])
    sprintf("<tr data-taxon=\"%s\"><th scope=\"row\">%s</th>%s</tr>", ids[i],
      if (linked[i]) sprintf("<a href=\"#%s\">%s</a>", ids[i], name) else name,
      paste(cells, collapse = ""))
  }, character(1))
  paste0(
    "<section class=\"matrix\" id=\"matrix\" aria-labelledby=\"h-matrix\">\n",
    "<h2 id=\"h-matrix\" tabindex=\"-1\">Pick any character you can see</h2>\n",
    "<p class=\"intro\">The table gives the state of each character in each taxon. ",
    "States separated by &quot;/&quot; both occur in the taxon; &quot;?&quot; is unknown or does not apply. ",
    "Strike out the taxa that do not fit what you see.</p>\n",
    "<details class=\"matrix-table\" open>\n<summary>The whole table</summary>\n<div class=\"table-scroll\">\n",
    "<table class=\"cmatrix\">\n<thead><tr><th scope=\"col\">Taxon</th>", paste(head, collapse = ""), "</tr></thead>\n",
    "<tbody>\n", paste(rows, collapse = "\n"), "\n</tbody>\n</table>\n</div>\n</details>\n</section>"
  )
}

# ---- offline copy --------------------------------------------------------------

wizJsonString <- function(x) {
  x <- gsub("\\", "\\\\", enc2utf8(x), fixed = TRUE)
  x <- gsub("\"", "\\\"", x, fixed = TRUE)
  x <- gsub("\n", "\\n", x, fixed = TRUE)
  x <- gsub("\r", "\\r", x, fixed = TRUE)
  x <- gsub("\t", "\\t", x, fixed = TRUE)
  x <- gsub("<", "\\u003c", x, fixed = TRUE)
  paste0("\"", x, "\"")
}

# A short fingerprint of a text, so that a changed page gets a new cache
wizHash <- function(x) {
  b <- as.numeric(charToRaw(enc2utf8(x)))
  sprintf("%08x%06x", as.integer(sum(b * (seq_along(b) %% 65521 + 1)) %% 2147483629), length(b) %% 16777216)
}

# Names of the files written next to the page, as paths and as the relative
# addresses the page and the worker use
wizOfflineNames <- function(file) {
  page <- basename(file)
  base <- sub("\\.[^.]*$", "", page)
  names <- c(manifest = paste0(base, ".webmanifest"), sw = paste0(base, "-sw.js"),
             icon192 = paste0(base, "-icon-192.png"), icon512 = paste0(base, "-icon-512.png"))
  url <- function(x) utils::URLencode(x, reserved = TRUE)
  # a page called index.html is usually served as its folder
  index <- tolower(page) %in% c("index.html", "index.htm")
  list(dir = dirname(file), page = page, base = base, files = names,
       url = c(page = url(page), vapply(names, url, "")),
       scope = if (index) "./" else paste0("./", url(page)))
}

wizWriteOffline <- function(side, html, title, external = character(), keep = character(), stamp = "") {
  path <- function(x) file.path(side$dir, side$files[[x]])
  icon <- function(size) list(src = side$url[[paste0("icon", size)]], size = size)
  manifest <- paste0(
    "{\n",
    "  \"name\": ", wizJsonString(title), ",\n",
    "  \"short_name\": ", wizJsonString(if (nchar(title) > 12) side$base else title), ",\n",
    "  \"description\": ", wizJsonString(paste("Identification key:", title)), ",\n",
    "  \"start_url\": ", wizJsonString(side$scope), ",\n",
    "  \"scope\": ", wizJsonString(side$scope), ",\n",
    "  \"display\": \"standalone\",\n",
    "  \"background_color\": \"#f6f3eb\",\n",
    "  \"theme_color\": \"#1d6b58\",\n",
    "  \"icons\": [\n",
    paste(vapply(c(192, 512), function(size) {
      sprintf("    {\"src\": %s, \"sizes\": \"%dx%d\", \"type\": \"image/png\", \"purpose\": \"any\"}",
        wizJsonString(icon(size)$src), size, size)
    }, ""), collapse = ",\n"),
    "\n  ]\n}\n"
  )
  wizWriteText(manifest, path("manifest"))
  wizIcon(path("icon192"), 192)
  wizIcon(path("icon512"), 512)

  sw <- paste(readLines(system.file("wizard", "sw.js", package = "dimoose"), warn = FALSE), collapse = "\n")
  prefix <- paste0("dimoose-", gsub("[^A-Za-z0-9_-]", "_", side$base), "-")
  array <- function(x) paste(wizJsonString(x), collapse = ", ")
  fill <- c(
    "\"__CACHE__\"" = wizJsonString(paste0(prefix, wizHash(paste(html, paste(external, collapse = "\n"))))),
    "\"__PREFIX__\"" = wizJsonString(prefix),
    "\"__KEPT__\"" = wizJsonString(paste0(prefix, "kept-", stamp)),
    "\"__PAGE__\"" = wizJsonString(side$url[["page"]]),
    "[/*__PRECACHE__*/]" = paste0("[", array(unname(side$url[c("page", "manifest", "icon192", "icon512")])), "]"),
    "[/*__EXTERNAL__*/]" = paste0("[", if (length(external)) array(external) else "", "]"),
    "[/*__KEEP__*/]" = paste0("[", if (length(keep)) array(unique(keep)) else "", "]")
  )
  for (token in names(fill)) sw <- sub(token, fill[[token]], sw, fixed = TRUE)
  wizWriteText(paste0(sw, "\n"), path("sw"))
  unname(vapply(names(side$files), path, ""))
}

# Figures the page loads from other sites (those not embedded in the key)
wizExternalImages <- function(leads, images) {
  urls <- unique(unlist(lapply(leads$Image, splitUrls)))
  if (length(urls) == 0) return(character())
  name <- sub("\\.(gif|jpe?g|png|webp)$", "", basename(urls), ignore.case = TRUE)
  urls[grepl("^https?://", urls) & !name %in% names(images)]
}

# App icon: the package logo when it can be drawn (needs rsvg), otherwise a
# plain drawn one.
wizIcon <- function(file, size) {
  logo <- c(system.file("help", "figures", "logo.svg", package = "dimoose"),
            system.file("man", "figures", "logo.svg", package = "dimoose"))
  logo <- logo[nzchar(logo)]
  if (length(logo) > 0 && requireNamespace("rsvg", quietly = TRUE)) {
    ok <- tryCatch({
      rsvg::rsvg_png(logo[1], file, width = size, height = size)
      file.exists(file) && file.size(file) > 0
    }, error = function(e) FALSE)
    if (ok) return(invisible(file))
  }
  wizDrawnIcon(file, size)
}

# A forking branch (one couplet, two leads) in the page's colours, written as
# a PNG with base R only.
wizDrawnIcon <- function(file, size) {
  u <- (seq_len(size) - 0.5) / size
  x <- base::matrix(u, size, size, byrow = TRUE)
  y <- base::matrix(u, size, size)
  w <- 0.035
  dot <- function(cx, cy, r = 0.085) (x - cx)^2 + (y - cy)^2 < r^2
  glyph <- (abs(x - 0.5) < w & y > 0.55 & y < 0.76) |
    (abs(y - 0.55) < w & x > 0.28 - w & x < 0.72 + w) |
    ((abs(x - 0.28) < w | abs(x - 0.72) < w) & y > 0.3 & y < 0.55) |
    dot(0.28, 0.27) | dot(0.72, 0.27) | dot(0.5, 0.76)
  rgb <- array(rep(c(0x1d, 0x6b, 0x58), each = size * size), c(size, size, 3))
  for (k in 1:3) rgb[, , k][glyph] <- c(0xf6, 0xf3, 0xeb)[k]
  wizWritePng(rgb, file)
}

# Minimal PNG writer: `rgb` is a rows x columns x 3 array of 0..255.
wizWritePng <- function(rgb, file) {
  h <- dim(rgb)[1]
  w <- dim(rgb)[2]
  # each scanline: filter byte 0, then R G B per pixel
  lines <- vapply(seq_len(h), function(i) c(0, as.vector(t(rgb[i, , ]))), numeric(1 + 3 * w))
  be32 <- function(n) as.raw(c(n %/% 16777216, (n %/% 65536) %% 256, (n %/% 256) %% 256, n %% 256))
  chunk <- function(type, data) {
    body <- c(charToRaw(type), data)
    c(be32(length(data)), body, wizCrc32(body))
  }
  png <- c(
    as.raw(c(0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a)),
    chunk("IHDR", c(be32(w), be32(h), as.raw(c(8, 2, 0, 0, 0)))),
    chunk("IDAT", memCompress(as.raw(as.vector(lines)), "gzip")),
    chunk("IEND", raw())
  )
  writeBin(png, file)
  invisible(file)
}

# CRC-32 of a raw vector as 4 bytes, kept in two 16-bit halves because R's
# bitwise functions work on signed 32-bit integers.
wizCrc32 <- function(bytes) {
  tab <- vapply(0:255, function(n) {
    hi <- 0L
    lo <- n
    for (k in 1:8) {
      odd <- bitwAnd(lo, 1L) == 1L
      lo <- bitwOr(bitwShiftR(lo, 1L), bitwShiftL(bitwAnd(hi, 1L), 15L))
      hi <- bitwShiftR(hi, 1L)
      if (odd) {
        hi <- bitwXor(hi, 0xEDB8L)
        lo <- bitwXor(lo, 0x8320L)
      }
    }
    c(hi, lo)
  }, integer(2))
  hi <- 0xFFFFL
  lo <- 0xFFFFL
  for (b in as.integer(bytes)) {
    i <- bitwAnd(bitwXor(lo, b), 255L) + 1L
    lo <- bitwXor(tab[2, i], bitwOr(bitwShiftR(lo, 8L), bitwShiftL(bitwAnd(hi, 255L), 8L)))
    hi <- bitwXor(tab[1, i], bitwShiftR(hi, 8L))
  }
  hi <- bitwXor(hi, 0xFFFFL)
  lo <- bitwXor(lo, 0xFFFFL)
  as.raw(c(hi %/% 256L, hi %% 256L, lo %/% 256L, lo %% 256L))
}

# ---- key checks --------------------------------------------------------------

normalizeLeads <- function(leads) {
  for (col in c("Statement", "Choice", "Character", "Next", "Taxon", "Label", "Image", "ImageLink", "TaxonUrl",
                "Question", "Feature", "Test")) {
    if (is.null(leads[[col]])) leads[[col]] <- rep("", nrow(leads))
    x <- as.character(leads[[col]])
    x[is.na(x)] <- ""
    leads[[col]] <- trimws(x)
  }
  if (is.null(leads$Threshold)) leads$Threshold <- rep(NA_real_, nrow(leads))
  leads$Threshold <- suppressWarnings(as.numeric(leads$Threshold))
  leads$Next[leads$Next == ""] <- "-"
  as.data.frame(leads, stringsAsFactors = FALSE)
}

# Display label of each lead: its Label if given, otherwise couplet + choice ("7b")
leadLabels <- function(leads) {
  ifelse(nzchar(leads$Label), leads$Label, paste0(leads$Statement, leads$Choice))
}

# Root couplet, reachability, parents and a list of problems found.
checkLeads <- function(leads) {
  couplets <- unique(leads$Statement)
  label <- leadLabels(leads)
  targets <- leads$Next[leads$Next != "-"]
  problems <- character()

  unreferenced <- setdiff(couplets, targets)
  root <- if (length(unreferenced) > 0) unreferenced[1] else couplets[1]
  if (length(unreferenced) == 0) {
    problems <- c(problems, "Every couplet is the target of some lead (the key has a cycle); starting at the first couplet")
  }

  missingTarget <- leads$Next != "-" & !leads$Next %in% couplets
  for (i in which(missingTarget)) {
    problems <- c(problems, sprintf("Lead %s leads to couplet %s, which is not in the key", label[i], leads$Next[i]))
  }
  noTaxon <- leads$Next == "-" & leads$Taxon == ""
  for (i in which(noTaxon)) {
    problems <- c(problems, sprintf("Lead %s ends the key but names no taxon", label[i]))
  }
  leadCount <- table(factor(leads$Statement, levels = couplets))
  for (cp in names(leadCount)[leadCount < 2]) {
    problems <- c(problems, sprintf("Couplet %s has only one lead", cp))
  }

  reachable <- root
  frontier <- root
  while (length(frontier) > 0) {
    nxt <- leads$Next[leads$Statement %in% frontier]
    nxt <- setdiff(nxt[nxt %in% couplets], reachable)
    reachable <- c(reachable, nxt)
    frontier <- nxt
  }
  unreachable <- setdiff(couplets, reachable)
  if (length(unreachable) > 0) {
    problems <- c(problems, sprintf(
      "Couplet(s) %s cannot be reached from couplet %s",
      paste(unreachable, collapse = ", "), root
    ))
  }

  list(root = root, couplets = couplets, missingTarget = missingTarget,
       unreachable = unreachable, problems = problems)
}

# Lead indices from the root to lead `i`, following the first parent lead of
# each couplet.
pathToLead <- function(leads, i, root, parentLead = match(leads$Statement, leads$Next)) {
  path <- i
  seen <- leads$Statement[i]
  while (leads$Statement[path[1]] != root) {
    parent <- parentLead[path[1]]
    if (is.na(parent) || leads$Statement[parent] %in% seen) break
    seen <- c(seen, leads$Statement[parent])
    path <- c(parent, path)
  }
  path
}

# ---- rendering ---------------------------------------------------------------

htmlEscape <- function(x) {
  x <- gsub("&", "&amp;", x, fixed = TRUE)
  x <- gsub("<", "&lt;", x, fixed = TRUE)
  x <- gsub(">", "&gt;", x, fixed = TRUE)
  x <- gsub("\"", "&quot;", x, fixed = TRUE)
  gsub("'", "&#39;", x, fixed = TRUE)
}

metaValue <- function(meta, key) {
  if (!is.data.frame(meta) || !all(c("key", "value") %in% names(meta))) return(NA_character_)
  v <- meta$value[meta$key == key]
  if (length(v) == 0) NA_character_ else as.character(v[1])
}

# Named vector: image id -> data URI, from meta rows image_<id>. Values that
# are bare base64 (importFishbase(embedImages = TRUE) wrote those) are GIFs.
embeddedImages <- function(meta) {
  if (!is.data.frame(meta) || !all(c("key", "value") %in% names(meta))) return(character())
  rows <- grepl("^image_", meta$key) & !grepl("^image_url_", meta$key)
  v <- as.character(meta$value[rows])
  v <- ifelse(startsWith(v, "data:"), v, paste0("data:image/gif;base64,", v))
  stats::setNames(v, sub("^image_", "", meta$key[rows]))
}

cssName <- function(id) paste0("--img-", gsub("[^A-Za-z0-9_-]", "_", id))

# <style> block declaring every embedded image once as a CSS custom property
imageStyle <- function(images) {
  if (length(images) == 0) return("")
  paste0("<style>:root{", paste0(cssName(names(images)), ":url(\"", images, "\")", collapse = ";"), "}</style>\n")
}

# Glossary of the key's sniglets: name, coined word, definition, example
# crops, where found. Anchors use the coined word, which never changes.
glossaryHtml <- function(features, leads, coupletId, images = character()) {
  if (is.null(features)) return("")
  terms <- which(features$kind == "centroid_patch_max")
  if (length(terms) == 0) return("")
  entries <- vapply(terms, function(j) {
    coined <- snigletWord(features$id[j])
    name <- features$label[j]
    ex <- features$exemplars[[j]]
    crops <- if (!is.null(ex) && !is.null(ex$png)) {
      # a crop the page already declares (patchExemplars() stores each one in
      # the key's images) is referenced, not embedded a second time
      uri <- paste0("data:image/png;base64,", ex$png)
      known <- paste0(gsub("[^A-Za-z0-9_-]", "_", coined), "_", seq_along(uri))
      shared <- !is.na(images[known]) & unname(images[known]) == uri
      paste0(sprintf("<span class=\"fig\" role=\"img\" aria-label=\"%s in %s\" style=\"background-image:%s\"></span>",
        htmlEscape(name), htmlEscape(ex$image),
        ifelse(shared, sprintf("var(%s)", cssName(known)), sprintf("url(&quot;%s&quot;)", uri))), collapse = "")
    } else ""
    seen <- if (is.null(ex)) NULL else if (!is.null(ex$label)) unique(ex$label) else unique(ex$image)
    where <- if (length(seen)) sprintf("<p class=\"found\">Seen in %s</p>", htmlEscape(paste(seen, collapse = ", "))) else ""
    asked <- unique(leads$Statement[leads$Feature == features$id[j]])
    links <- paste(sprintf("<a href=\"#%s\">%s</a>", coupletId(asked), htmlEscape(asked)), collapse = ", ")
    def <- if (!is.null(features$definition) && !is.na(features$definition[j])) sprintf("<p class=\"definition\">%s</p>", htmlEscape(features$definition[j])) else ""
    was <- if (!identical(name, coined)) sprintf("<p class=\"found\">Sniglet <code>%s</code></p>", htmlEscape(coined)) else ""
    sprintf("<div class=\"term\" id=\"g-%s\"><h3%s>%s</h3>%s<div class=\"figs\">%s</div>%s%s<p class=\"found\">Asked at %s</p></div>",
      htmlEscape(coined), if (identical(name, coined)) "" else " class=\"named\"", htmlEscape(name), def, crops, where, was, links)
  }, character(1))
  sprintf("<section class=\"glossary\" id=\"glossary\" aria-labelledby=\"h-glossary\">\n<h2 id=\"h-glossary\" tabindex=\"-1\">Glossary of sniglets</h2>\n<p>A sniglet is a visual feature the model found in the images. Each one is defined by the image patches that match it best: \"Has <i>sniglet</i>\" means the specimen has a region that looks like these.</p>\n%s\n</section>",
    paste(entries, collapse = "\n"))
}

splitUrls <- function(x) {
  if (is.na(x) || !nzchar(x)) character() else strsplit(x, ";", fixed = TRUE)[[1]]
}

figuresHtml <- function(thumbs, fulls, images, alt) {
  if (length(thumbs) == 0) return("")
  items <- vapply(thumbs, function(t) {
    name <- sub("\\.(gif|jpe?g|png|webp)$", "", basename(t), ignore.case = TRUE)
    full <- fulls[basename(fulls) == sub("^tn_", "", basename(t))][1]
    img <- if (!is.na(images[name])) {
      sprintf("<span class=\"fig\" role=\"img\" aria-label=\"%s\" style=\"background-image:var(%s)\"></span>",
        htmlEscape(alt), cssName(name))
    } else {
      sprintf("<img class=\"fig\" src=\"%s\" alt=\"%s\" loading=\"lazy\">", htmlEscape(t), htmlEscape(alt))
    }
    if (is.na(full)) img else {
      sprintf("<a href=\"%s\" target=\"_blank\" rel=\"noopener\" title=\"Open full-size figure\">%s</a>", htmlEscape(full), img)
    }
  }, character(1))
  paste0("<figure class=\"figs\">", paste(items, collapse = ""), "</figure>")
}

renderWizard <- function(leads, check, title, citation, taxa, images, displayLinks, map = TRUE,
                         nodeLabel = "Couplet", staticPaths = TRUE, features = NULL,
                         matrix = NULL, offline = NULL, photo = NULL, note = NA_character_) {
  hasKey <- nrow(leads) > 0   # FALSE for a page made from a character matrix alone
  map <- isTRUE(map) && hasKey
  label <- leadLabels(leads)
  # Section ids: sanitized names, made unique (e.g. M4'67 and M4"67)
  ids <- if (hasKey) paste0("c-", gsub("[^A-Za-z0-9_-]", "_", check$couplets)) else character()
  ids <- ifelse(duplicated(ids) | duplicated(ids, fromLast = TRUE), paste0(ids, "-", seq_along(ids)), ids)
  names(ids) <- check$couplets
  coupletId <- function(cp) unname(ids[cp])

  terminal <- which(leads$Next == "-" & leads$Taxon != "")
  taxonNames <- unique(leads$Taxon[terminal])
  taxonId <- stats::setNames(paste0("t-", seq_along(taxonNames))[seq_along(taxonNames)], taxonNames)

  # Notes on leads (pruneKey() writes the character of a collapsed couplet there)
  leadNote <- if (is.null(leads$Note)) rep("", nrow(leads)) else trimws(as.character(leads$Note))
  leadNote[is.na(leadNote)] <- ""
  noteHtml <- ifelse(nzchar(leadNote), sprintf("<span class=\"note\"><b>Also:</b> %s</span>", htmlEscape(leadNote)), "")

  # Couplet sections
  coupletHtml <- vapply(check$couplets, function(cp) {
    idx <- which(leads$Statement == cp)
    parents <- which(leads$Next == cp)
    from <- if (length(parents) > 0) {
      sprintf(" <span class=\"from\">from %s</span>", paste(sprintf(
        "<a href=\"#%s\">%s</a>", coupletId(leads$Statement[parents]),
        htmlEscape(ifelse(label[parents] == cp, leads$Statement[parents], label[parents]))
      ), collapse = ", "))
    } else {
      ""
    }
    leadItems <- vapply(idx, function(i) {
      text <- if (nzchar(leads$Character[i])) leads$Character[i] else "(no description)"
      if (leads$Next[i] == "-") {
        if (nzchar(leads$Taxon[i])) {
          href <- paste0("#", taxonId[[leads$Taxon[i]]])
          dest <- paste0("&rarr; ", htmlEscape(leads$Taxon[i]))
        } else {
          href <- NA
          dest <- "no taxon given"
        }
      } else if (check$missingTarget[i]) {
        href <- NA
        dest <- sprintf("&rarr; couplet %s (missing from key)", htmlEscape(leads$Next[i]))
      } else {
        href <- paste0("#", coupletId(leads$Next[i]))
        dest <- paste0("&rarr; ", htmlEscape(leads$Next[i]))
      }
      inner <- sprintf(
        "<span class=\"letter\" aria-hidden=\"true\">%s</span><span class=\"text\">%s</span>%s<span class=\"dest\">%s</span>",
        if (nzchar(leads$Choice[i])) htmlEscape(leads$Choice[i]) else "&bull;", htmlEscape(text), noteHtml[i], dest
      )
      choose <- if (is.na(href)) {
        sprintf("<span class=\"choose broken\" data-lead=\"%s\">%s</span>", htmlEscape(label[i]), inner)
      } else {
        sprintf("<a class=\"choose\" href=\"%s\" data-lead=\"%s\">%s</a>", href, htmlEscape(label[i]), inner)
      }
      figs <- figuresHtml(splitUrls(leads$Image[i]), splitUrls(leads$ImageLink[i]), images,
        paste("Figure for lead", label[i]))
      gloss <- ""
      if (!is.null(features) && nzchar(leads$Feature[i])) {
        fr <- match(leads$Feature[i], features$id)
        if (!is.na(fr) && features$kind[fr] == "centroid_patch_max") {
          gloss <- sprintf("<a class=\"gloss\" href=\"#g-%s\" title=\"What is this? See the glossary\" aria-label=\"Glossary entry for this sniglet\">?</a>",
            htmlEscape(snigletWord(features$id[fr])))
        }
      }
      sprintf("<li class=\"lead%s\">%s%s%s</li>", if (nzchar(gloss)) " examples" else "", choose, gloss, figs)
    }, character(1))
    id <- coupletId(cp)
    q <- if (!is.null(leads$Question)) leads$Question[idx[1]] else ""
    heading <- if (!is.null(q) && nzchar(q)) {
      sprintf("%s <span class=\"num\">%s %s</span>", htmlEscape(q), htmlEscape(nodeLabel), htmlEscape(cp))
    } else {
      sprintf("%s <span class=\"num\">%s</span>", htmlEscape(nodeLabel), htmlEscape(cp))
    }
    sprintf(
      "<section class=\"couplet\" id=\"%s\" aria-labelledby=\"h-%s\" data-name=\"%s\">\n<h2 id=\"h-%s\" tabindex=\"-1\">%s%s</h2>\n<ul class=\"leads\">\n%s\n</ul>\n</section>",
      id, id, htmlEscape(paste(nodeLabel, cp)), id, heading, from, paste(leadItems, collapse = "\n")
    )
  }, character(1))

  # Taxon result sections
  parentLead <- match(leads$Statement, leads$Next)
  terminalsOf <- split(terminal, factor(leads$Taxon[terminal], levels = taxonNames))
  taxaRow <- if (is.data.frame(taxa) && "submitted_name" %in% names(taxa)) match(taxonNames, taxa$submitted_name) else rep(NA, length(taxonNames))
  names(taxaRow) <- taxonNames
  taxonHtml <- vapply(taxonNames, function(tx) {
    i <- terminalsOf[[tx]][1]
    steps <- if (staticPaths) {
      path <- pathToLead(leads, i, check$root, parentLead)
      vapply(path, function(p) {
        sprintf("<li><a class=\"step\" href=\"#%s\">%s</a>%s%s</li>",
          coupletId(leads$Statement[p]), htmlEscape(label[p]), htmlEscape(leads$Character[p]), noteHtml[p])
      }, character(1))
    } else {
      "<li class=\"pending\">The path through the key appears here when the page script runs.</li>"
    }
    verified <- ""
    if (!is.na(taxaRow[[tx]]) && "matched_name" %in% names(taxa)) {
      row <- taxa[taxaRow[[tx]], , drop = FALSE]
      if (nrow(row) > 0 && !is.na(row$matched_name[1]) && row$matched_name[1] != tx) {
        src <- if (!is.null(row$data_source) && !is.na(row$data_source[1])) paste0(" (", row$data_source[1], ")") else ""
        verified <- sprintf("<p class=\"verified\">Accepted name: %s%s</p>", htmlEscape(row$matched_name[1]), htmlEscape(src))
      }
    }
    others <- terminalsOf[[tx]]
    alsoVia <- if (length(others) > 1) {
      sprintf("<p class=\"verified\">Also reached from lead %s.</p>", htmlEscape(paste(label[others[-1]], collapse = ", ")))
    } else {
      ""
    }
    url <- leads$TaxonUrl[i]
    link <- if (nzchar(url)) sprintf("<a href=\"%s\" target=\"_blank\" rel=\"noopener\">More on FishBase</a>", htmlEscape(url)) else ""
    id <- taxonId[[tx]]
    sprintf(
      "<section class=\"taxon\" id=\"%s\" aria-labelledby=\"h-%s\">\n<p class=\"eyebrow\">Identified as</p>\n<h2 id=\"h-%s\" tabindex=\"-1\">%s</h2>\n%s%s<h3>Path through the key</h3>\n<ol class=\"diagnosis\"%s>\n%s\n</ol>\n<p class=\"actions\"><a href=\"#%s\">Identify another specimen</a>%s</p>\n</section>",
      id, id, id, htmlEscape(tx), verified, alsoVia, if (staticPaths) "" else " data-auto=\"1\"",
      paste(steps, collapse = "\n"), coupletId(check$root), link
    )
  }, character(1))

  warningsHtml <- if (length(check$problems) > 0) {
    sprintf("<div class=\"warnings\" role=\"note\"><strong>Problems found in this key</strong><ul>%s</ul></div>",
      paste0("<li>", htmlEscape(check$problems), "</li>", collapse = ""))
  } else {
    ""
  }
  citationHtml <- if (!is.na(citation) && nzchar(citation)) sprintf("<p class=\"cite\">%s</p>", htmlEscape(citation)) else ""
  if (length(note) == 1 && !is.na(note) && nzchar(note)) {
    citationHtml <- paste0(citationHtml, sprintf("\n<p class=\"pruned\"><span class=\"note\"><b>All taxa of this key:</b> %s</span></p>", htmlEscape(note)))
  }

  mapHtml <- if (map) renderMap(leads, check, coupletId, taxonId, nodeLabel) else ""

  # Character matrix: its taxa are matched to the key's by name, so that they
  # share the result sections and the map
  matrixHtml <- ""
  if (!is.null(matrix)) {
    row <- match(matrix$taxa, taxonNames)
    loose <- match(tolower(matrix$taxa), tolower(trimws(taxonNames)))
    row[is.na(row)] <- loose[is.na(row)]
    if (hasKey && anyNA(row)) {
      message(sum(is.na(row)), " of ", length(row), " taxa of the matrix are not results of the key and get no link: ",
              paste(utils::head(matrix$taxa[is.na(row)], 10), collapse = ", "), if (sum(is.na(row)) > 10) ", ..." else "")
    }
    matrixIds <- ifelse(is.na(row), paste0("m-", seq_along(row)), unname(taxonId)[row])
    matrixHtml <- paste0(if (hasKey) "<h2 class=\"group\">Characters</h2>\n" else "",
                         wizMatrixHtml(matrix, matrixIds, !is.na(row)), "\n")
  }
  rootId <- if (hasKey) coupletId(check$root) else "matrix"
  head <- body <- foot <- ""
  if (!is.null(offline)) {
    head <- sprintf("<link rel=\"manifest\" href=\"%s\">\n<link rel=\"apple-touch-icon\" href=\"%s\">\n<link rel=\"icon\" type=\"image/png\" href=\"%s\">\n",
      offline$url[["manifest"]], offline$url[["icon192"]], offline$url[["icon192"]])
    body <- sprintf(" data-sw=\"%s\" data-sw-scope=\"%s\"", offline$url[["sw"]], offline$scope)
    foot <- "<span id=\"mk-offline\" hidden></span>"
  }
  if (!is.null(photo)) {
    body <- paste0(body, sprintf(" data-photo-model=\"%s\" data-photo-runtime=\"%s\"", htmlEscape(photo$url), htmlEscape(photo$runtime)),
                   if (!is.na(photo$runtimeBytes)) sprintf(" data-photo-runtime-bytes=\"%.0f\"", photo$runtimeBytes) else "")
  }

  css <- paste(readLines(system.file("wizard", "wizard.css", package = "dimoose"), warn = FALSE), collapse = "\n")
  js <- paste(readLines(system.file("wizard", "wizard.js", package = "dimoose"), warn = FALSE), collapse = "\n")

  paste0(
    "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n",
    "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n",
    "<meta name=\"theme-color\" content=\"#f6f3eb\" media=\"(prefers-color-scheme: light)\">\n",
    "<meta name=\"theme-color\" content=\"#131a1b\" media=\"(prefers-color-scheme: dark)\">\n",
    "<meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n",
    "<meta name=\"mobile-web-app-capable\" content=\"yes\">\n",
    "<meta name=\"generator\" content=\"dimoose ", utils::packageVersion("dimoose"), "\">\n",
    "<title>", htmlEscape(title), "</title>\n", head, "<style>\n", css, "\n</style>\n", imageStyle(images), "</head>\n",
    "<body data-root=\"", rootId, "\"", body, if (!isTRUE(displayLinks)) " class=\"nolinks\"" else "", ">\n",
    "<header class=\"masthead\">\n<p class=\"eyebrow\">", if (hasKey) "Dichotomous key" else "Multi-access key", "</p>\n<h1>", htmlEscape(title), "</h1>\n", citationHtml, "\n",
    "<nav class=\"toolbar\" aria-label=\"Key navigation\">",
    "<button type=\"button\" id=\"mk-back\" disabled>&larr; Back</button>",
    "<a href=\"#", rootId, "\" id=\"mk-restart\">Start over</a>",
    "<span class=\"spacer\"></span>",
    if (hasKey && !is.null(matrix)) "<button type=\"button\" id=\"mk-pick\" aria-pressed=\"false\"><span class=\"long\">Pick characters</span><span class=\"short\">Pick</span></button>" else "",
    if (map) "<button type=\"button\" id=\"mk-maptoggle\" aria-controls=\"mk-map\" aria-expanded=\"false\">Map</button>" else "",
    if (hasKey) "<button type=\"button\" id=\"mk-mode\" aria-pressed=\"false\"><span class=\"long\">Show full key</span><span class=\"short\">Full key</span></button>" else "",
    "</nav>\n",
    "<ol class=\"trail\" id=\"mk-trail\" aria-label=\"Choices so far\" aria-live=\"polite\"></ol>\n</header>\n",
    "<div class=\"columns", if (map) " has-map" else "", "\">\n", mapHtml,
    "<main>\n", warningsHtml, "\n", paste(coupletHtml, collapse = "\n"), "\n",
    if (length(taxonHtml) > 0) "<h2 class=\"group\">Taxa</h2>\n" else "",
    paste(taxonHtml, collapse = "\n"), "\n", matrixHtml, glossaryHtml(features, leads, coupletId, images), "\n</main>\n</div>\n",
    "<footer><p>",
    if (hasKey) paste0(length(check$couplets), if (nodeLabel == "Couplet") " couplets, " else " steps, ",
      length(taxonNames), if (nodeLabel == "Couplet") " taxa. " else " possible results. ")
    else paste0(length(matrix$characters), " characters, ", length(matrix$taxa), " taxa. "),
    if (hasKey) "<span class=\"hint\">Press a, b (or 1, 2) to choose a lead, u if you are not sure. </span>" else "",
    foot, "Generated by the dimoose R package.</p></footer>\n",
    "<script>\n", js, "\n</script>\n</body>\n</html>\n"
  )
}

# ---- key map -----------------------------------------------------------------

# Inline SVG drawing of the key as a tree: couplets at their depth from the
# root (left to right), terminal leads as named leaves on the right. A couplet
# reached from more than one lead is drawn once; the extra links are dashed.
# Every node links to its section and carries data attributes the page script
# uses to mark the current position, the path so far and what is still ahead.
renderMap <- function(leads, check, coupletId, taxonId, nodeLabel = "Couplet") {
  label <- leadLabels(leads)
  # Long couplet names (e.g. haplogroups) do not fit inside a node: draw small
  # nodes and show names only along the user's path (see wizard.css).
  named <- max(nchar(check$couplets)) > 3
  rowH <- 20
  pad <- 14
  r <- if (named) 4.5 else 8.5

  nodes <- list()
  edges <- list()
  extra <- list()
  placed <- character()
  row <- 0

  visit <- function(cp, depth, anc) {
    placed <<- c(placed, cp)
    me <- coupletId(cp)
    ys <- numeric()
    for (i in which(leads$Statement == cp)) {
      nx <- leads$Next[i]
      if (nx == "-") {
        if (!nzchar(leads$Taxon[i])) next
        row <<- row + 1
        key <- paste0("L", i)
        nodes[[key]] <<- list(kind = "leaf", target = taxonId[[leads$Taxon[i]]], x = depth + 1, y = row,
                              label = leads$Taxon[i], anc = c(anc, me))
        edges[[length(edges) + 1]] <<- list(from = me, to = key, lead = label[i], text = leads$Character[i])
        ys <- c(ys, row)
      } else if (nx %in% check$couplets && !nx %in% placed) {
        ys <- c(ys, visit(nx, depth + 1, c(anc, me)))
        edges[[length(edges) + 1]] <<- list(from = me, to = coupletId(nx), lead = label[i], text = leads$Character[i])
      } else if (nx %in% placed) {
        extra[[length(extra) + 1]] <<- list(from = me, to = coupletId(nx), lead = label[i], text = leads$Character[i])
      }
    }
    if (length(ys) == 0) {
      row <<- row + 1
      ys <- row
    }
    y <- (min(ys) + max(ys)) / 2
    nodes[[me]] <<- list(kind = "couplet", target = me, x = depth, y = y, label = cp, anc = anc)
    y
  }
  visit(check$root, 0, character())

  leafNodes <- Filter(function(n) n$kind == "leaf", nodes)
  labelW <- if (length(leafNodes)) max(nchar(vapply(leafNodes, `[[`, "", "label"))) * 6.4 + 14 else 0
  depth <- max(1, vapply(nodes, `[[`, 0, "x"))
  # Narrow the columns (down to 20px) so typical keys fit a ~400px panel
  colW <- max(20, min(30, (400 - labelW - 2 * pad - r) / depth))
  px <- function(n) pad + r + n$x * colW
  py <- function(n) pad + (n$y - 1) * rowH
  width <- ceiling(pad + r + depth * colW + labelW + pad)
  height <- ceiling(2 * pad + (row - 1) * rowH)

  edgeSvg <- vapply(edges, function(e) {
    a <- nodes[[e$from]]
    b <- nodes[[e$to]]
    endX <- px(b) - if (b$kind == "couplet") r else 3.5
    sprintf(
      "<path class=\"medge\" data-from=\"%s\" data-to=\"%s\" d=\"M%.1f %.1fV%.1fH%.1f\"><title>%s %s</title></path>",
      e$from, b$target, px(a), py(a), py(b), endX,
      htmlEscape(e$lead), htmlEscape(e$text)
    )
  }, character(1))
  extraSvg <- vapply(extra, function(e) {
    a <- nodes[[e$from]]
    b <- nodes[[e$to]]
    sprintf(
      "<path class=\"medge cross\" data-from=\"%s\" data-to=\"%s\" d=\"M%.1f %.1fL%.1f %.1f\"><title>%s %s (also leads to couplet %s)</title></path>",
      e$from, e$to, px(a), py(a), px(b), py(b),
      htmlEscape(e$lead), htmlEscape(e$text), htmlEscape(b$label)
    )
  }, character(1))
  nodeSvg <- vapply(names(nodes), function(k) {
    n <- nodes[[k]]
    anc <- if (length(n$anc)) n$anc[length(n$anc)] else ""
    if (n$kind == "couplet") {
      sprintf(
        "<a class=\"mnode mcouplet\" href=\"#%s\" data-id=\"%s\" data-p=\"%s\" data-x=\"%.0f\" data-y=\"%.0f\" aria-label=\"%s %s\"><circle cx=\"%.1f\" cy=\"%.1f\" r=\"%.1f\"/><text x=\"%.1f\" y=\"%.1f\">%s</text></a>",
        n$target, n$target, anc, px(n), py(n), htmlEscape(nodeLabel), htmlEscape(n$label),
        px(n), py(n), r, if (named) px(n) + 6 else px(n), if (named) py(n) - 6 else py(n) + 3.2, htmlEscape(n$label)
      )
    } else {
      sprintf(
        "<a class=\"mnode mleaf\" href=\"#%s\" data-id=\"%s\" data-p=\"%s\" data-x=\"%.0f\" data-y=\"%.0f\" aria-label=\"%s\"><circle cx=\"%.1f\" cy=\"%.1f\" r=\"3.5\"/><text x=\"%.1f\" y=\"%.1f\">%s</text></a>",
        n$target, n$target, anc, px(n), py(n), htmlEscape(n$label),
        px(n), py(n), px(n) + 8, py(n) + 3.5, htmlEscape(n$label)
      )
    }
  }, character(1))

  nTaxa <- length(unique(vapply(leafNodes, `[[`, "", "target")))
  paste0(
    "<aside class=\"map\" id=\"mk-map\" aria-label=\"Map of the key\">\n",
    "<div class=\"map-head\"><span class=\"eyebrow\">Map of the key</span>",
    "<span class=\"map-count\" id=\"mk-left\" aria-live=\"polite\">", nTaxa, " taxa</span></div>\n",
    "<div class=\"map-scroll\" id=\"mk-map-scroll\">\n",
    sprintf("<svg class=\"keymap%s\" width=\"%d\" height=\"%d\" viewBox=\"0 0 %d %d\" xmlns=\"http://www.w3.org/2000/svg\">\n", if (named) " named" else "", width, height, width, height),
    "<g class=\"edges\">", paste(c(edgeSvg, extraSvg), collapse = ""), "</g>\n",
    "<g class=\"nodes\">", paste(nodeSvg, collapse = ""), "</g>\n</svg>\n</div>\n",
    "<p class=\"map-legend\"><span class=\"k here\"></span>You are here <span class=\"k done\"></span>Your path <span class=\"k ahead\"></span>Still possible</p>\n",
    "</aside>\n"
  )
}

# ---- R/features.R ------------------------------------------------------------
#' A table of machine-computable features
#'
#' Keys built from images (see [keyFromTerms()] and [keyFromClusters()]) carry
#' a `features` table that says how a machine computes the score each lead
#' tests. [classify()] walks a key over a matrix of such scores.
#'
#' @param id Feature ids, e.g. `"sniglet:dulmzil"` or `"text:round_headlights"`.
#' @param kind `"centroid_patch_max"` (highest cosine similarity between any
#'   image patch embedding and `embedding`), `"clip_text_pair"` (cosine with
#'   `prompt` minus cosine with `negative_prompt`) or `"external"` (computed
#'   by the user).
#' @param label Name shown to people; defaults to `id`.
#' @param prompt,negative_prompt Texts for `clip_text_pair` features.
#' @param region Crop as `"y0,y1,x0,x1"` fractions, or `NA` for the whole image.
#' @param definition Optional sentence saying what the feature is, shown in
#'   the wizard's glossary (see [renameSniglets()]).
#' @param embedding List of numeric vectors (one per feature), or `NULL`.
#' @param exemplars List of data frames with columns `image`, `patch`,
#'   `score` and optionally `png` (base64) showing what the feature means.
#' @return A data frame with the columns above; `embedding` and `exemplars`
#'   are list columns.
#' @examples
#' featureTable("sniglet:x", "centroid_patch_max", embedding = list(c(1, 0, 0)))
#' @export
featureTable <- function(id, kind, label = id, prompt = NA, negative_prompt = NA, region = NA,
                         embedding = NULL, exemplars = NULL, definition = NA) {
  n <- length(id)
  if (is.null(embedding)) embedding <- vector("list", n)
  if (is.null(exemplars)) exemplars <- vector("list", n)
  stopifnot(length(kind) == n || length(kind) == 1, length(embedding) == n, length(exemplars) == n)
  out <- data.frame(
    id = as.character(id), kind = as.character(rep_len(kind, n)), label = as.character(rep_len(label, n)),
    prompt = as.character(rep_len(prompt, n)), negative_prompt = as.character(rep_len(negative_prompt, n)),
    region = as.character(rep_len(region, n)), definition = as.character(rep_len(definition, n)),
    stringsAsFactors = FALSE
  )
  out$embedding <- embedding
  out$exemplars <- exemplars
  out
}

# Problems with the Feature/Test/Threshold columns of a lead table, given the
# key's features table (NULL when the key has none).
checkFeatures <- function(leads, features) {
  if (is.null(leads$Feature)) return(character())
  used <- which(!is.na(leads$Feature) & nzchar(leads$Feature))
  if (length(used) == 0) return(character())
  problems <- character()
  if (is.null(features)) {
    return("Leads test features but the key has no features table")
  }
  missing <- setdiff(unique(leads$Feature[used]), features$id)
  if (length(missing)) {
    problems <- c(problems, sprintf("Feature %s is tested by a lead but not in the features table", missing))
  }
  badTest <- used[!leads$Test[used] %in% c(">", "<=")]
  if (length(badTest)) {
    problems <- c(problems, sprintf("Lead %s%s has Test %s; use > or <=", leads$Statement[badTest],
      leads$Choice[badTest], leads$Test[badTest]))
  }
  thr <- suppressWarnings(as.numeric(leads$Threshold[used]))
  if (any(is.na(thr))) {
    problems <- c(problems, sprintf("Lead %s%s has no numeric Threshold",
      leads$Statement[used[is.na(thr)]], leads$Choice[used[is.na(thr)]]))
  }
  for (cp in unique(leads$Statement[used])) {
    i <- used[leads$Statement[used] == cp]
    if (length(i) == 2 && leads$Feature[i[1]] == leads$Feature[i[2]] && leads$Test[i[1]] == leads$Test[i[2]]) {
      problems <- c(problems, sprintf("Couplet %s tests %s with the same Test on both leads; they must be opposite", cp, leads$Feature[i[1]]))
    }
    if (length(i) == 2 && leads$Feature[i[1]] != leads$Feature[i[2]]) {
      problems <- c(problems, sprintf("Couplet %s tests two different features (%s, %s); both leads of a couplet must test the same feature",
        cp, leads$Feature[i[1]], leads$Feature[i[2]]))
    }
  }
  problems
}

#' Follow a key by machine
#'
#' Walks each row of `scores` through `key`: at every couplet the lead whose
#' test (`Feature`, `Test`, `Threshold`) passes is taken. When no lead or
#' more than one passes (for instance on a missing score), the result is `NA`.
#'
#' @param key A [dimoose] key with `Feature`, `Test` and `Threshold` lead
#'   columns, e.g. from [keyFromTerms()].
#' @param scores A numeric matrix, one row per object, with a column for every
#'   feature id the key tests (see [featureScores()] and [scoreImages()]).
#' @return A data frame with `id` (row names of `scores`), `result` and
#'   `path` (the leads taken, e.g. `"1a 3b"`).
#' @export
classify <- function(key, scores) {
  leads <- normalizeLeads(key$leads)
  needed <- unique(leads$Feature[nzchar(leads$Feature)])
  if (length(needed) == 0) stop("This key has no machine-readable tests", call. = FALSE)
  if (is.null(dim(scores))) scores <- matrix(scores, 1, dimnames = list(NULL, names(scores)))
  # Score columns may be keyed by feature id (featureScores/scoreImages), by a
  # sniglet's coined word (snigletScores output) or by the feature's label;
  # map them to ids so any of these works.
  f <- key$features
  if (!is.null(f)) {
    alias <- c(stats::setNames(f$id, sub("^[^:]*:", "", f$id)), stats::setNames(f$id, f$label))
    alias <- alias[!duplicated(names(alias))]
    hit <- colnames(scores) %in% names(alias) & !colnames(scores) %in% f$id
    colnames(scores)[hit] <- alias[colnames(scores)[hit]]
  }
  missing <- setdiff(needed, colnames(scores))
  if (length(missing)) stop("`scores` is missing scores for: ", paste(missing, collapse = ", "), call. = FALSE)
  root <- checkLeads(leads)$root
  byCouplet <- split(seq_len(nrow(leads)), leads$Statement)
  ids <- rownames(scores); if (is.null(ids)) ids <- as.character(seq_len(nrow(scores)))
  walk <- function(s) {
    cp <- root; path <- character(); seen <- character()
    repeat {
      if (cp %in% seen) return(list(NA_character_, path))
      seen <- c(seen, cp)
      i <- byCouplet[[cp]]
      v <- s[leads$Feature[i]]
      ok <- ifelse(leads$Test[i] == ">", v > leads$Threshold[i], v <= leads$Threshold[i])
      ok[is.na(ok)] <- FALSE
      if (sum(ok) != 1) return(list(NA_character_, path))
      take <- i[ok]
      path <- c(path, paste0(leads$Statement[take], leads$Choice[take]))
      if (leads$Next[take] == "-") return(list(leads$Taxon[take], path))
      cp <- leads$Next[take]
      if (!cp %in% names(byCouplet)) return(list(NA_character_, path))
    }
  }
  res <- lapply(seq_len(nrow(scores)), function(r) walk(stats::setNames(scores[r, ], colnames(scores))))
  data.frame(id = ids, result = vapply(res, `[[`, "", 1),
             path = vapply(res, function(x) paste(x[[2]], collapse = " "), ""), stringsAsFactors = FALSE)
}

#' Accuracy of a key followed by machine
#'
#' @inheritParams classify
#' @param labels True label of each row of `scores`.
#' @param groups Optional named vector mapping labels to coarser groups (e.g.
#'   model years to generations) for a second accuracy figure.
#' @return A list: `results` (one row per object with `actual`, `predicted`,
#'   `correct`, `groupCorrect`), `accuracy`, `groupAccuracy` and `confusion`.
#' @export
evaluateKey <- function(key, scores, labels, groups = NULL) {
  r <- classify(key, scores)
  r$actual <- as.character(labels)
  r$predicted <- r$result; r$result <- NULL
  r$correct <- !is.na(r$predicted) & r$predicted == r$actual
  r$groupCorrect <- if (is.null(groups)) NA else !is.na(r$predicted) & groups[r$predicted] == groups[r$actual]
  r$groupCorrect[is.na(r$groupCorrect)] <- FALSE
  list(results = r[, c("id", "actual", "predicted", "correct", "groupCorrect", "path")],
       accuracy = mean(r$correct),
       groupAccuracy = if (is.null(groups)) NA_real_ else mean(r$groupCorrect),
       confusion = table(actual = r$actual, predicted = ifelse(is.na(r$predicted), "<none>", r$predicted)))
}

#' Leave-one-out evaluation of a key builder
#'
#' @param images [imageSet()] data frame of all images.
#' @param build Function of the training row indices returning a key.
#' @param score Function of (key, test row index) returning a one-row scores
#'   matrix for that image.
#' @param groups As in [evaluateKey()].
#' @return As [evaluateKey()].
#' @export
looKey <- function(images, build, score, groups = NULL) {
  n <- nrow(images)
  rows <- lapply(seq_len(n), function(i) {
    key <- build(setdiff(seq_len(n), i))
    r <- classify(key, score(key, i))
    data.frame(id = images$id[i], actual = images$label[i], predicted = r$result[1], path = r$path[1], stringsAsFactors = FALSE)
  })
  r <- do.call(rbind, rows)
  r$correct <- !is.na(r$predicted) & r$predicted == r$actual
  r$groupCorrect <- if (is.null(groups)) NA else !is.na(r$predicted) & groups[r$predicted] == groups[r$actual]
  r$groupCorrect[is.na(r$groupCorrect)] <- FALSE
  list(results = r[, c("id", "actual", "predicted", "correct", "groupCorrect", "path")],
       accuracy = mean(r$correct),
       groupAccuracy = if (is.null(groups)) NA_real_ else mean(r$groupCorrect),
       confusion = table(actual = r$actual, predicted = ifelse(is.na(r$predicted), "<none>", r$predicted)))
}

#' Compute a key's feature scores from embeddings
#'
#' Model-free: give it the embeddings and it applies each feature's rule.
#' `centroid_patch_max` features need `patches`; `clip_text_pair` features
#' need `image` and `textEmb` (rows named by prompt). For `external`
#' features supply the scores yourself.
#'
#' @param key A [dimoose] key with a `features` table.
#' @param image `objects x d` matrix of image embeddings (unit rows).
#' @param patches `objects x patches x d` array of patch embeddings.
#' @param textEmb `prompts x d` matrix of text embeddings whose row names are
#'   the prompt texts, e.g. from [embedTexts()].
#' @return An `objects x features` matrix with feature ids as column names.
#' @seealso [scoreImages()] for images-to-scores in one call.
#' @export
featureScores <- function(key, image = NULL, patches = NULL, textEmb = NULL) {
  f <- key$features
  if (is.null(f)) stop("This key has no features table", call. = FALSE)
  n <- if (!is.null(image)) nrow(image) else if (!is.null(patches)) dim(patches)[1] else stop("Give `image` or `patches`", call. = FALSE)
  ids <- if (!is.null(image)) rownames(image) else dimnames(patches)[[1]]
  out <- matrix(NA_real_, n, nrow(f), dimnames = list(ids, f$id))
  for (j in seq_len(nrow(f))) {
    kind <- f$kind[j]
    if (kind == "centroid_patch_max") {
      if (is.null(patches)) stop("Feature ", f$id[j], " needs `patches`", call. = FALSE)
      out[, j] <- snigletScores(patches, matrix(f$embedding[[j]], 1))[, 1]
    } else if (kind == "clip_text_pair") {
      if (is.null(image) || is.null(textEmb)) stop("Feature ", f$id[j], " needs `image` and `textEmb`", call. = FALSE)
      for (p in c(f$prompt[j], f$negative_prompt[j])) if (!p %in% rownames(textEmb)) stop("`textEmb` has no row for the prompt: ", p, call. = FALSE)
      out[, j] <- image %*% textEmb[f$prompt[j], ] - image %*% textEmb[f$negative_prompt[j], ]
    } else if (kind != "external") {
      stop("Unknown feature kind: ", kind, call. = FALSE)
    }
  }
  out
}

# ---- R/images.R ------------------------------------------------------------
#' A set of labelled images
#'
#' The starting point for automated key generation: one row per photo, with
#' the class (species, model, ...) the photo shows. A key separates the
#' classes, so there must be at least two.
#'
#' @param paths Image files, or a single folder. A folder is searched
#'   (with its subfolders) for image files: png, jpg/jpeg, gif, webp, bmp and
#'   tif/tiff.
#' @param label Class of each image:
#'   * `NULL`: for a folder whose images are in subfolders, the name of the
#'     subfolder each image is in (`pics/cardinal/IMG_01.jpg` is a
#'     `cardinal`); otherwise the file name without its extension;
#'   * a character vector as long as `paths` (for a folder, as long as the
#'     files found, which are sorted by path);
#'   * a function applied to the file names without extensions (e.g.
#'     `function(x) sub("_.*$", "", x)` so that `1967_alt` counts as `1967`).
#' @return A data frame with `id`, `path` and `label`. `id` is the file name
#'   without its extension; when two files share a name, their folder is put
#'   in front (`cardinal_IMG_01`) so that ids are unique.
#' @examples
#' imageSet(c("pics/1967.png", "pics/1967_alt.png"), label = function(x) sub("_.*$", "", x))
#' imageSet(c("pics/cardinal/1.jpg", "pics/robin/1.jpg"), label = c("cardinal", "robin"))
#' # the example photos that ship with dimoose: one folder per fruit
#' pics <- imageSet(system.file("extdata", "pics", package = "dimoose"))
#' table(pics$label)
#' @export
imageSet <- function(paths, label = NULL) {
  paths <- as.character(paths)
  fromFolder <- length(paths) == 1 && dir.exists(paths)
  if (fromFolder) {
    root <- paths
    paths <- sort(list.files(root, pattern = "\\.(png|jpe?g|gif|webp|bmp|tiff?)$", ignore.case = TRUE,
                             recursive = TRUE, full.names = TRUE))
    if (!length(paths)) stop("No image files found in ", root, call. = FALSE)
  } else if (length(paths) == 1 && !file.exists(paths) && !grepl("\\.[A-Za-z0-9]+$", paths)) {
    stop("No such folder: ", paths, call. = FALSE)
  }
  name <- sub("\\.[^.]+$", "", basename(paths))
  folder <- basename(dirname(paths))
  id <- name
  dup <- id %in% id[duplicated(id)]
  id[dup] <- paste(folder[dup], name[dup], sep = "_")
  id <- make.unique(id, sep = "_")
  lab <- if (is.null(label)) {
    inSubfolder <- if (fromFolder) normalizePath(dirname(paths)) != normalizePath(root) else FALSE
    if (any(inSubfolder) && !all(inSubfolder)) {
      warning("Some images are in subfolders of ", root, " and some are not, so each image is labelled by its file name; ",
              "move the loose images into a class folder, or pass `label`", call. = FALSE)
    }
    if (all(inSubfolder)) folder else name
  } else if (is.function(label)) {
    as.character(label(name))
  } else {
    if (length(label) != length(paths)) stop("`label` must have one entry per path (length ", length(paths), ")", call. = FALSE)
    as.character(label)
  }
  data.frame(id = id, path = paths, label = lab, stringsAsFactors = FALSE)
}

#' MIME type of an image file from its first bytes
#' @param path One file.
#' @return `"image/png"`, `"image/jpeg"`, `"image/gif"`, `"image/webp"` or `NA`.
#' @export
imageMime <- function(path) {
  b <- readBin(path, "raw", 12)
  hex <- paste(format(b), collapse = "")
  if (startsWith(hex, "89504e47")) return("image/png")
  if (startsWith(hex, "ffd8ff")) return("image/jpeg")
  if (startsWith(hex, "474946")) return("image/gif")
  if (startsWith(hex, "52494646") && substr(hex, 17, 24) == "57454250") return("image/webp")
  NA_character_
}

#' Embed images in a key's metadata
#'
#' Reads image files and returns `image_<id>` rows for a key's `meta`, which
#' [exportWizard()] embeds in the page (each image once); leads refer to them
#' by id in their `Image` column (several separated by `;`).
#'
#' @param paths Image files.
#' @param ids Names for the images; default the file names without extension.
#' @param maxSize Photos larger than this many pixels on their long side are
#'   scaled down to it when the 'magick' package is installed, so keys made
#'   from camera photos stay small; without 'magick' they are embedded as they are.
#' @return A key/value data frame.
#' @export
imageMeta <- function(paths, ids = NULL, maxSize = 1200) {
  if (is.null(ids)) ids <- sub("\\.[^.]+$", "", basename(paths))
  shrink <- canUse("magick")
  value <- vapply(paths, function(p) {
    mime <- imageMime(p)
    if (is.na(mime)) stop(basename(p), " is not an image", call. = FALSE)
    bytes <- if (shrink) shrinkImage(p, maxSize, sub("^image/", "", mime)) else NULL
    if (is.null(bytes)) bytes <- p
    paste0("data:", mime, ";base64,", base64enc::base64encode(bytes))
  }, character(1))
  data.frame(key = paste0("image_", ids), value = unname(value), stringsAsFactors = FALSE)
}

# Is an optional (Suggests) package available? A function of its own so that
# tests can pretend a package is missing.
canUse <- function(pkg) requireNamespace(pkg, quietly = TRUE)

# The image (a file path or raw bytes) scaled down with magick to fit in
# maxSize x maxSize pixels, as raw bytes in `format`; NULL when it already fits.
shrinkImage <- function(image, maxSize, format) {
  img <- magick::image_read(image)
  info <- magick::image_info(img)
  if (max(info$width, info$height) <= maxSize) return(NULL)
  img <- magick::image_resize(img, sprintf("%dx%d>", maxSize, maxSize))
  magick::image_write(img, format = format)
}

# ---- R/keys.R ------------------------------------------------------------
#' Build a dimoose key from a table of leads
#'
#' The common constructor behind [sharkKey()], [arachnidaKey()],
#' [vibrioKey()] and [phylotreeKey()]: takes one row per lead and returns a
#' [dimoose] object.
#'
#' @param leads Data frame with columns `Statement` (couplet), `Choice`,
#'   `Character` (the lead's text), `Next` (next couplet, or `"-"` if the lead
#'   ends in a result) and `Taxon` (the result, for terminal leads). Optional
#'   columns `Label`, `Image`, `ImageLink` and `TaxonUrl` are used by
#'   [exportWizard()]; any others are kept.
#' @param desc Title or description of the key.
#' @param meta Key/value data frame of metadata (e.g. `citation`).
#' @param taxa Data frame of results with `submitted_name` and
#'   `matched_name`; by default every taxon matches itself.
#' @param features Optional [featureTable()] for keys a machine can follow
#'   (the leads then also carry `Feature`, `Test` and `Threshold`).
#' @return A [dimoose] object.
#' @examples
#' leads <- data.frame(
#'   Statement = c("1", "1", "2", "2"), Choice = c("a", "b", "a", "b"),
#'   Character = c("Wings present", "Wings absent", "Two wings", "Four wings"),
#'   Next = c("2", "-", "-", "-"), Taxon = c("", "Apterygota", "Diptera", "Other")
#' )
#' k <- keyFromLeads(leads, "A tiny key")
#' k
#' k$toNewick()
#' @export
keyFromLeads <- function(leads, desc = NA, meta = NULL, taxa = NULL, features = NULL) {
  if (!is.data.frame(leads)) stop("`leads` must be a data frame", call. = FALSE)
  missing <- setdiff(c("Statement", "Choice", "Character", "Next", "Taxon"), names(leads))
  if (length(missing)) {
    stop("`leads` is missing column(s): ", paste(missing, collapse = ", "), call. = FALSE)
  }
  leads <- as.data.frame(leads, stringsAsFactors = FALSE)
  for (col in c("Statement", "Choice", "Character", "Next", "Taxon")) {
    x <- as.character(leads[[col]])
    x[is.na(x)] <- ""
    leads[[col]] <- x
  }
  leads$Next[leads$Next == ""] <- "-"
  if (is.null(meta)) {
    meta <- data.frame(key = character(), value = character(), stringsAsFactors = FALSE)
  }
  if (is.null(taxa)) {
    tx <- unique(leads$Taxon[leads$Next == "-" & nzchar(leads$Taxon)])
    taxa <- data.frame(submitted_name = tx, matched_name = tx, stringsAsFactors = FALSE)
  }
  if (!is.null(leads$Threshold)) leads$Threshold <- as.numeric(leads$Threshold)
  dimoose$new(keyPaths(leads, separateTerms = FALSE), desc, meta, taxa, leads = leads, features = features)
}

#' Build a dimoose key from a classification tree
#'
#' Converts an [rpart::rpart()] classification tree into a dichotomous key:
#' every split becomes a couplet with two leads, and every leaf a result.
#' Taxa that the tree cannot separate share a leaf and are listed together
#' (`"A / B"`). A taxon rpart could not send down either side of a split,
#' because the split's variable is missing for it, is listed at every result
#' below that split.
#'
#' @param fit An `rpart` object with `method = "class"`, e.g. from
#'   [generateTree()].
#' @param desc Title of the key.
#' @param meta Key/value metadata data frame.
#' @return A [dimoose] object.
#' @seealso [keyFromMatrix()], which builds a key straight from a character
#'   matrix and handles variable taxa; [vibrioKey()]
#' @examples
#' d <- data.frame(
#'   taxon = factor(c("A", "B", "C")),
#'   wings = factor(c("+", "-", "-")),
#'   spots = factor(c("-", "+", "-"))
#' )
#' fit <- generateTree(d, "taxon")
#' keyFromRpart(fit, "Three taxa")$leads
#' @export
keyFromRpart <- function(fit, desc = "Key generated from a classification tree", meta = NULL) {
  if (!inherits(fit, "rpart") || is.null(attr(fit, "ylevels"))) {
    stop("`fit` must be a classification rpart tree", call. = FALSE)
  }
  frame <- fit$frame
  node <- as.integer(rownames(frame))
  leaf <- frame$var == "<leaf>"
  if (all(leaf)) stop("The tree has no splits", call. = FALSE)
  if (is.null(fit$y)) stop("Refit with y = TRUE so leaf members are known", call. = FALSE)
  # A lead reads "character: state". Only the "=" rpart puts after the
  # character's name is replaced, not one in the name or in a state. (Numeric
  # splits keep their historical form, "x< 2" and "x>: 2".)
  lab <- labels(fit, minlength = 0L)
  asked <- as.character(frame$var)[match(node %/% 2L, node)]
  byState <- !is.na(asked) & startsWith(lab, paste0(asked, "="))
  lab[byState] <- paste0(asked[byState], ": ", substring(lab[byState], nchar(asked[byState]) + 2L))
  lab[!byState] <- gsub("=", ": ", lab[!byState], fixed = TRUE)
  members <- split(attr(fit, "ylevels")[fit$y], factor(fit$where, levels = seq_len(nrow(frame))))
  # rpart leaves a row at a split when the split's variable is missing for it
  # and no surrogate places it. Such a taxon could be on either side, so it
  # is listed at every result below that split.
  for (k in which(leaf)) {
    up <- node[k] %/% 2L
    while (up >= 1L) {
      members[[k]] <- c(members[[k]], members[[match(up, node)]])
      up <- up %/% 2L
    }
  }

  internal <- node[!leaf]
  number <- stats::setNames(as.character(seq_along(internal)), internal)
  rows <- lapply(internal, function(n) {
    kids <- match(c(2L * n, 2L * n + 1L), node)
    data.frame(
      Statement = number[[as.character(n)]],
      Choice = c("a", "b"),
      Character = lab[kids],
      Next = ifelse(leaf[kids], "-", number[as.character(node[kids])]),
      Taxon = vapply(kids, function(k) {
        if (!leaf[k]) return("")
        paste(sort(unique(members[[k]])), collapse = " / ")
      }, character(1)),
      stringsAsFactors = FALSE
    )
  })
  keyFromLeads(do.call(rbind, rows), desc, meta)
}

#' Example keys
#'
#' Ready-made [dimoose] keys built from the datasets that come with dimoose. All
#' five are ordinary dimoose objects: they share the same fields (`leads`,
#' `df`, `meta`, `taxa`, `desc`) and methods (`print()`, `summary()`,
#' `validate()`, `toDataTree()`, `toNewick()`) and all work with
#' [exportWizard()].
#'
#' - `sharkKey()`: FishBase key 1, *Key to the families of sharks in the
#'   Western Central Pacific* (Compagno 1998), from saved FishBase pages in
#'   `inst/extdata/fishbase/`; 23 couplets, 24 families.
#' - `arachnidaKey()`: the *Key to the Orders of Arachnida* from Triplehorn &
#'   Johnson (2005), the [arachnida] dataset; 11 couplets, 11 orders
#'   (Schizomida is reached from two couplets).
#' - `vibrioKey()`: a key generated from the [vibrio] consensus matrix of
#'   Noguerola & Blanch (2008) with [keyFromMatrix()] (the matrix itself is
#'   [vibrioMatrix()]). Tests scored `+` or `(+)` count as positive and `-` or
#'   `(-)` as negative. With `variable = "both"` (the default) a species
#'   that is variable for a test (`v`, `d`) is keyed out down both leads of
#'   every couplet that uses the test, and so is a species the test was not
#'   determined for (`ND`): 92 couplets, 74 species, 14 of them reached at
#'   two or three results. With `variable = "missing"` those results are
#'   treated as missing and the key is an rpart classification tree
#'   ([keyFromRpart()]), which places such a species on one side of the test
#'   with surrogate splits: 73 couplets, each species at one result, but a
#'   strain showing the species' other result is keyed out wrongly.
#' - `montanaKey()`: the native broadleaf trees of Montana, written for
#'   dimoose (the [montana] dataset); 10 couplets, 11 species, with photos
#'   from Wikimedia Commons. It is built with [keyFromSpreadsheet()] from
#'   `inst/extdata/montana/montana-key.csv`, a template for writing your own.
#' - [phylotreeKey()]: PhyloTree Build 17.
#'
#' @param variable For `vibrioKey()`: `"both"` (default) keys a species
#'   that is variable for a test out down both leads; `"missing"` treats
#'   variable results as missing. See [keyFromMatrix()].
#' @return A [dimoose] object.
#' @references
#' Compagno LJV (1998). General remarks. In Carpenter KE, Niem VH (eds.),
#' *FAO species identification guide for fishery purposes. The living marine
#' resources of the Western Central Pacific*, vol. 2, pp. 1196-1207. FAO,
#' Rome. FishBase key 1: <https://www.fishbase.se/keys/description.php?keycode=1>.
#'
#' Triplehorn CA, Johnson NF (2005). *Borror and DeLong's Introduction to the
#' Study of Insects*, 7th ed., chapter 5. Thomson Brooks/Cole. ISBN
#' 0-03-096835-6.
#'
#' Noguerola I, Blanch AR (2008). Identification of *Vibrio* spp. with a set
#' of dichotomous keys. *Journal of Applied Microbiology* 105, 175-185.
#' \doi{10.1111/j.1365-2672.2008.03730.x}
#' @examples
#' sharks <- sharkKey()
#' sharks
#' summary(arachnidaKey())
#' vibrioKey()$validate()
#' summary(vibrioKey(variable = "missing"))
#' \dontrun{
#' exportWizard(sharkKey(), "sharks.html")
#' }
#' @name exampleKeys
NULL

#' @rdname exampleKeys
#' @export
sharkKey <- function() {
  dir <- system.file("extdata", "fishbase", package = "dimoose")
  parseFishbase(
    file.path(dir, "key1-description.html"),
    file.path(dir, "key1-questions.html"),
    usePhyloService = "none"
  )
}

#' @rdname exampleKeys
#' @export
arachnidaKey <- function() {
  keyFromLeads(
    dimoose::arachnida,
    desc = "Key to the Orders of Arachnida",
    meta = data.frame(
      key = "citation",
      value = paste(
        "Triplehorn CA, Johnson NF (2005). Borror and DeLong's Introduction to",
        "the Study of Insects, 7th ed., chapter 5. Thomson Brooks/Cole."
      ),
      stringsAsFactors = FALSE
    )
  )
}

#' @rdname exampleKeys
#' @export
vibrioKey <- function(variable = c("both", "missing")) {
  variable <- match.arg(variable)
  keyFromMatrix(
    vibrioMatrix(),
    variable = variable,
    desc = "Vibrio species (key generated from the Noguerola & Blanch 2008 matrix)",
    meta = data.frame(
      key = "citation",
      value = paste(
        "Noguerola I, Blanch AR (2008). Identification of Vibrio spp. with a set of",
        "dichotomous keys. J Appl Microbiol 105:175-185.",
        if (variable == "both") {
          paste("Key generated with dimoose; species with variable or undetermined",
                "results follow both leads.")
        } else {
          "Key generated with rpart; variable and not determined results treated as missing."
        }
      ),
      stringsAsFactors = FALSE
    )
  )
}

#' @rdname exampleKeys
#' @export
montanaKey <- function() {
  keyFromSpreadsheet(
    system.file("extdata", "montana", "montana-key.csv", package = "dimoose"),
    desc = "Key to the native broadleaf trees of Montana",
    meta = data.frame(
      key = "citation",
      value = paste(
        "Key written for dimoose from the Montana Field Guide (Montana Natural Heritage",
        "Program and Montana Fish, Wildlife & Parks), USDA PLANTS and Virginia Tech",
        "Dendrology. Photos from Wikimedia Commons; authors and licenses in the",
        "package's COPYRIGHTS file."
      ),
      stringsAsFactors = FALSE
    )
  )
}

#' Key to the Orders of Arachnida
#'
#' The key from Triplehorn & Johnson (2005), *Borror and DeLong's
#' Introduction to the Study of Insects*, 7th ed., chapter 5, as a table of
#' leads (see [keyFromLeads()]); [arachnidaKey()] turns it into a [dimoose]
#' key. Transcribed by hand from the book.
#'
#' @format A data frame with 22 rows (11 couplets) and 6 columns:
#' \describe{
#'   \item{Statement}{Couplet number.}
#'   \item{Choice}{`a` for the first lead (`1.`), `b` for the second (`1'.`).}
#'   \item{Character}{Text of the lead.}
#'   \item{Next}{Couplet the lead leads to, or `"-"`.}
#'   \item{Taxon}{Order the lead ends in, for terminal leads.}
#'   \item{Page}{Page of the book where that order is treated.}
#' }
#' @source Triplehorn CA, Johnson NF (2005). *Borror and DeLong's
#'   Introduction to the Study of Insects*, 7th ed. Thomson Brooks/Cole.
#'   Transcription: `data-raw/arachnida/` in the package sources.
"arachnida"

#' Vibrio consensus identification matrix
#'
#' Biochemical and growth test results for 74 *Vibrio* taxa from Noguerola &
#' Blanch (2008), one row per taxon. [vibrioKey()] generates a key from it
#' and [vibrioMatrix()] recodes it for [keyFromMatrix()].
#'
#' @format A data frame with 74 rows and 46 columns: `species`, then 45 tests
#'   coded as in the paper: `+` positive, `-` negative, `(+)` / `(-)` mostly
#'   positive / negative, `v` or `d` variable, `ND` not determined (and one
#'   blank cell in the source, `NA`). Tests under the paper's "Acid from" and
#'   "Resistance to" headings are named with that prefix.
#' @source Noguerola I, Blanch AR (2008). Identification of *Vibrio* spp.
#'   with a set of dichotomous keys. *Journal of Applied Microbiology* 105,
#'   175-185. \doi{10.1111/j.1365-2672.2008.03730.x}. Extracted from the
#'   paper's table; see `data-raw/vibrio/` in the package sources.
"vibrio"

#' Key to the native broadleaf trees of Montana
#'
#' A dichotomous key to the eleven native broadleaf (hardwood) trees of
#' Montana, as a table of leads (see [keyFromLeads()]); [montanaKey()] turns it
#' into a [dimoose] key with photos. Written for dimoose: native status was
#' checked in the Montana Field Guide and USDA PLANTS, and every couplet's
#' characters come from Montana Field Guide or Virginia Tech Dendrology
#' descriptions. Common hackberry is left out because the Montana Field Guide
#' gives its origin in Montana as undetermined.
#'
#' @format A data frame with 20 rows (10 couplets) and 7 character columns:
#' \describe{
#'   \item{Statement}{Couplet number.}
#'   \item{Choice}{`a` or `b`.}
#'   \item{Character}{Text of the lead.}
#'   \item{Next}{Couplet the lead leads to, or `"-"`.}
#'   \item{Taxon}{For terminal leads, `"Common name (Genus species)"`.}
#'   \item{Question}{What the couplet asks, e.g. `"Leaf type?"`.}
#'   \item{Image}{Ids of the photos in `inst/extdata/montana/` shown with the
#'     lead, separated by `;`.}
#' }
#' @source Montana Field Guide, Montana Natural Heritage Program and Montana
#'   Fish, Wildlife & Parks, <https://fieldguide.mt.gov>; USDA PLANTS
#'   Database, <https://plants.usda.gov>; Virginia Tech Dendrology fact sheets,
#'   <https://dendro.cnre.vt.edu>. The page for each species and the source of
#'   each couplet are listed in `data-raw/montana/sources.md` in the package
#'   sources.
"montana"

# ---- R/spreadsheet.R ------------------------------------------------------------
#' Build a key from a spreadsheet
#'
#' Reads a key written in a spreadsheet and saved as CSV (in Excel or
#' Google Sheets: *File > Save as / Download > CSV*). Each row is one lead:
#'
#' - `Couplet`: the couplet's number.
#' - `Description`: what the lead says ("Leaves compound.").
#' - `Goes to`: the couplet this lead leads to, or blank when the lead
#'   ends in a species.
#' - `Species`: the result, for leads that end the key. Write it as
#'   `"Common name (Genus species)"` to have [keyDiagram()] set the
#'   scientific name in italics.
#' - `Choice` (optional): the lead's letter; by default the leads of each
#'   couplet are lettered a, b, c in the order they appear (after z come
#'   aa, ab and so on).
#' - `Question` (optional): what the couplet asks ("Leaf type?"), shown by
#'   [keyDiagram()] and [exportWizard()].
#' - `Photo` (optional): file names of photos to show with the lead,
#'   separated by commas or semicolons; the extension may be left out. A
#'   web address (`https://...`) is kept as a link to the picture instead.
#' - `Note` and `Label` (optional): a remark on the lead, as [pruneKey()]
#'   writes, and a label to show for the lead in place of couplet and
#'   letter. Both are kept in the key's leads as they are.
#'
#' Column names are matched loosely (case, spaces and punctuation do not
#' matter) and dimoose's own names work too: `Statement`, `Character`,
#' `Next`, `Taxon` and `Image`. Other columns are ignored and blank rows are
#' skipped. The photos are embedded in the key, so the wizard and the
#' diagram work offline.
#'
#' The file may be as Excel saves it: with or without a byte-order mark, in
#' UTF-8 or Windows-1252, and with semicolons between the cells, which is
#' what Excel writes where the comma is the decimal mark.
#'
#' The Montana key that comes with dimoose is a ready-made example to copy:
#' `system.file("extdata", "montana", "montana-key.csv", package = "dimoose")`,
#' with its photos in the same folder.
#'
#' @param file Path of the CSV file (UTF-8).
#' @param photos Folder holding the photos named in the `Photo` column; by
#'   default the folder the CSV file is in.
#' @param desc Title of the key.
#' @param meta Optional key/value metadata data frame (e.g. a `citation`
#'   row); the photos are added to it.
#' @param checkNames If `TRUE`, check the species names against GBIF with
#'   [checkNames()] and warn, by spreadsheet row, about names that are
#'   misspelled, outdated synonyms or unknown. Needs an internet connection.
#' @return A [dimoose] key.
#' @seealso [keyToSpreadsheet()] to write a key as such a spreadsheet,
#'   [keyFromLeads()] to build a key from a data frame,
#'   [keyDiagram()] and [exportWizard()] to show it.
#' @examples
#' csv <- system.file("extdata", "montana", "montana-key.csv", package = "dimoose")
#' k <- keyFromSpreadsheet(csv, desc = "Native broadleaf trees of Montana")
#' k
#' keyDiagram(k, tempfile(fileext = ".svg"))
#' @export
keyFromSpreadsheet <- function(file, photos = NULL, desc = NA, meta = NULL, checkNames = FALSE) {
  if (!file.exists(file)) stop("Spreadsheet ", file, " not found", call. = FALSE)
  # Excel saves "CSV UTF-8" with a byte-order mark, and plain "CSV" on Windows
  # as Windows-1252; read either as UTF-8
  text <- rawToChar(readBin(file, "raw", file.size(file)))
  if (!validUTF8(text)) text <- iconv(text, "CP1252", "UTF-8")
  Encoding(text) <- "UTF-8"
  text <- sub("^\ufeff", "", text)
  # A comma inside an unquoted cell shifts every cell after it; catch that
  # before read.csv quietly pads or wraps the row
  countCells <- function(text, sep) {
    con <- textConnection(text)
    on.exit(close(con))
    utils::count.fields(con, sep = sep, quote = "\"", blank.lines.skip = FALSE, comment.char = "")
  }
  # Excel separates cells with semicolons where the comma is the decimal mark
  header <- sub("[\r\n].*$", "", sub("^[\r\n]+", "", text))
  sep <- if (nzchar(header) && countCells(header, ";")[1] > countCells(header, ",")[1]) ";" else ","
  cells <- countCells(text, sep)
  wide <- which(!is.na(cells) & cells > cells[1])
  if (length(wide)) {
    stop(sprintf("Row %d has more cells than the header row; put quotes around a cell that contains a %s",
                 wide[1], if (sep == ";") "semicolon" else "comma"), call. = FALSE)
  }
  sheet <- utils::read.csv(text = text, sep = sep, colClasses = "character", check.names = FALSE,
                           na.strings = character(), strip.white = TRUE, blank.lines.skip = FALSE, encoding = "UTF-8")
  # Match column names loosely: "Goes to", "goes_to" and "GOESTO" are the same
  aliases <- c(couplet = "Statement", statement = "Statement", choice = "Choice",
               description = "Character", character = "Character", goesto = "Next", "next" = "Next",
               species = "Taxon", taxon = "Taxon", question = "Question", photo = "Image", photos = "Image",
               image = "Image", images = "Image", note = "Note", notes = "Note", label = "Label")
  canon <- aliases[gsub("[^a-z]", "", tolower(names(sheet)))]
  keep <- !is.na(canon)
  sheet <- stats::setNames(sheet[keep], canon[keep])
  for (col in c("Statement", "Character")) {
    if (is.null(sheet[[col]])) {
      stop("The spreadsheet needs a ", c(Statement = "Couplet", Character = "Description")[[col]], " column", call. = FALSE)
    }
  }
  for (col in c("Choice", "Next", "Taxon", "Question", "Image")) {
    if (is.null(sheet[[col]])) sheet[[col]] <- rep("", nrow(sheet))
    sheet[[col]] <- trimws(sheet[[col]])
  }
  row <- seq_len(nrow(sheet)) + 1L
  blank <- !nzchar(trimws(do.call(paste0, sheet)))
  sheet <- sheet[!blank, , drop = FALSE]
  row <- row[!blank]
  sheet$Statement <- trimws(sheet$Statement)
  sheet$Next[sheet$Next == "-"] <- ""

  problems <- character()
  both <- nzchar(sheet$Next) & nzchar(sheet$Taxon)
  neither <- !nzchar(sheet$Next) & !nzchar(sheet$Taxon)
  missing <- nzchar(sheet$Next) & !sheet$Next %in% sheet$Statement
  problems <- c(problems,
    sprintf("Row %d has both `Goes to` (%s) and `Species` (%s); a lead does one or the other", row[both], sheet$Next[both], sheet$Taxon[both]),
    sprintf("Row %d has neither `Goes to` nor `Species`", row[neither]),
    sprintf("Row %d goes to couplet %s, which is not in the sheet", row[missing], sheet$Next[missing]))
  if (length(problems)) stop(paste(problems, collapse = "\n"), call. = FALSE)

  # Letter the leads that have no Choice (a to z, then aa, ab, ...), skipping
  # letters already used
  sheet$Choice <- stats::ave(sheet$Choice, sheet$Statement, FUN = function(x) {
    x[!nzchar(x)] <- setdiff(qualChoiceLetters(length(x)), x)[seq_len(sum(!nzchar(x)))]
    x
  })
  # Couplet M lead 11 and couplet M1 lead 1 are different leads that would
  # both be written "M11", so compare couplet and letter, not the two pasted
  again <- which(duplicated(sheet[c("Statement", "Choice")]))
  if (length(again)) {
    first <- which(sheet$Statement == sheet$Statement[again[1]] & sheet$Choice == sheet$Choice[again[1]])[1]
    stop(sprintf("Rows %d and %d are both lead %s; give them different Choice letters",
                 row[first], row[again[1]], paste0(sheet$Statement[again[1]], sheet$Choice[again[1]])), call. = FALSE)
  }
  sheet$Next[!nzchar(sheet$Next)] <- "-"

  if (is.null(meta)) meta <- data.frame(key = character(), value = character(), stringsAsFactors = FALSE)
  # Web addresses stay as they are; everything else names a photo file
  isUrl <- function(x) grepl("^https?://", x)
  photoNames <- function(cell) {
    parts <- trimws(strsplit(cell, ";", fixed = TRUE)[[1]])
    parts <- unlist(lapply(parts, function(x) if (isUrl(x)) x else trimws(strsplit(x, ",", fixed = TRUE)[[1]])))
    parts[nzchar(parts)]
  }
  named <- which(nzchar(sheet$Image))
  linked <- vapply(sheet$Image[named], function(cell) all(isUrl(photoNames(cell))), logical(1))
  for (i in named[linked]) sheet$Image[i] <- paste(photoNames(sheet$Image[i]), collapse = ";")
  named <- named[!linked]
  if (length(named)) {
    if (is.null(photos)) photos <- dirname(file)
    available <- list.files(photos)
    ids <- character()
    paths <- character()
    for (i in named) {
      wanted <- photoNames(sheet$Image[i])
      found <- vapply(wanted, function(w) {
        if (isUrl(w)) return(w)
        hit <- available[available == w | sub("\\.[^.]+$", "", available) == w]
        if (length(hit)) hit[1] else NA_character_
      }, character(1))
      if (anyNA(found)) {
        stop(sprintf("Row %d: photo %s not found in %s", row[i], wanted[is.na(found)][1], photos), call. = FALSE)
      }
      onDisk <- !isUrl(found)
      id <- ifelse(onDisk, sub("\\.[^.]+$", "", found), found)
      sheet$Image[i] <- paste(id, collapse = ";")
      paths <- c(paths, file.path(photos, found[onDisk]))
      ids <- c(ids, id[onDisk])
    }
    first <- !duplicated(ids)
    meta <- rbind(meta, imageMeta(paths[first], ids[first]))
  }

  leads <- sheet[c("Statement", "Choice", "Character", "Next", "Taxon", "Question", "Image",
                   intersect(c("Note", "Label"), names(sheet)))]
  rownames(leads) <- NULL
  key <- keyFromLeads(leads, desc, meta)
  if (isTRUE(checkNames)) {
    checked <- dimoose::checkNames(key)
    bad <- checked[checked$status %in% c("misspelled", "synonym", "not found"), ]
    if (nrow(bad)) {
      at <- row[match(bad$Taxon, sheet$Taxon)]
      warning("Some species names do not match GBIF:\n",
              paste(paste0("Row ", at, ": ", bad$note)[order(at)], collapse = "\n"), call. = FALSE)
    }
  }
  key
}

#' Write a key as a spreadsheet
#'
#' Writes a key as the CSV file that [keyFromSpreadsheet()] reads, so that a
#' key imported from FishBase or generated from data can be opened in Excel
#' or Google Sheets, edited by hand and read back. The columns are those of
#' the Montana template: `Couplet`, `Choice`, `Question`, `Description`,
#' `Goes to`, `Species` and `Photo`, followed by `Note` and `Label` when
#' the key's leads have them (a pruned key has notes, see [pruneKey()]; a
#' PhyloTree key has labels).
#'
#' Photos embedded in the key (see [imageMeta()]) are written as image files
#' into `photos`, named by their ids, and the `Photo` column names those
#' files. A file of that name that is already there with different contents
#' is left alone and used as it is, so writing a key back next to its
#' original photos does not replace them with the smaller embedded copies.
#' Pictures a lead refers to by web address stay web addresses.
#'
#' Reading the file back gives the same leads and the same photo ids. The
#' exceptions are small: a photo id that cannot be a file name (it has a
#' `/`, `:`, comma or the like in it, or differs from another only by
#' capitals) is changed, with a message; a line break inside a cell comes
#' back as a plain line feed whatever it was; and leads without a `Choice`
#' are lettered.
#'
#' A spreadsheet holds only those columns. Anything else in the key's
#' leads (for example the taxon links of a FishBase key, or the tests of a
#' key a machine can follow) is not written, and a message says which
#' columns were left out; the title and citation are not written either, so
#' pass `desc` and `meta` again to [keyFromSpreadsheet()].
#'
#' @param key A [dimoose] key.
#' @param file Path of the CSV file to write (UTF-8).
#' @param photos Folder to write the key's embedded photos into; by default
#'   the folder the CSV file is in. It is created if needed.
#' @param bom Start the file with a byte-order mark? Excel needs one to
#'   show accented and other non-English letters correctly when the file is
#'   opened by double-clicking; Google Sheets and [keyFromSpreadsheet()]
#'   read the file either way. Use `FALSE` for programs that do not expect
#'   one.
#' @return `file`, invisibly, so the result can go straight to
#'   [keyFromSpreadsheet()].
#' @seealso [keyFromSpreadsheet()]
#' @examples
#' dir <- tempfile("key")
#' dir.create(dir)
#' csv <- keyToSpreadsheet(montanaKey(), file.path(dir, "montana.csv"))
#' list.files(dir)
#' # ... edit the file in a spreadsheet program, then read it back
#' again <- keyFromSpreadsheet(csv, desc = "Montana trees, edited")
#' identical(again$leads$Character, montanaKey()$leads$Character)
#' @export
keyToSpreadsheet <- function(key, file, photos = NULL, bom = TRUE) {
  if (!inherits(key, "dimoose")) stop("`key` must be a dimoose object", call. = FALSE)
  if (!is.character(file) || length(file) != 1 || is.na(file) || !nzchar(file)) {
    stop("`file` must be the path of the CSV file to write", call. = FALSE)
  }
  raw <- key$leads
  leads <- normalizeLeads(raw)
  if (nrow(leads) == 0) stop("This key has no leads to write", call. = FALSE)
  if (is.null(photos)) photos <- dirname(file)

  # Each embedded photo becomes a file; the Photo cell names it
  embedded <- embeddedImages(key$meta)
  written <- character()
  missing <- character()
  photoCell <- vapply(leads$Image, function(cell) {
    ids <- trimws(splitUrls(cell))
    ids <- ids[nzchar(ids)]
    names <- vapply(ids, function(id) {
      if (grepl("^https?://", id)) return(id)
      if (!id %in% names(embedded)) {
        missing <<- c(missing, id)
        return(NA_character_)
      }
      if (is.na(written[id])) written[id] <<- qualPhotoFile(id, embedded[[id]], photos, written)
      written[[id]]
    }, character(1))
    paste(names[!is.na(names)], collapse = "; ")
  }, character(1), USE.NAMES = FALSE)
  if (length(missing)) {
    warning("Photo(s) not embedded in the key, so left out of the spreadsheet: ",
            paste(unique(missing), collapse = ", "), call. = FALSE)
  }
  renamed <- names(written) != sub("\\.[^.]+$", "", written)
  if (any(renamed)) {
    message("Photo ids that cannot be file names were changed: ",
            paste(sprintf("%s is now %s", names(written)[renamed], sub("\\.[^.]+$", "", written[renamed])), collapse = ", "))
  }

  sheet <- data.frame(
    Couplet = leads$Statement, Choice = leads$Choice, Question = leads$Question, Description = leads$Character,
    `Goes to` = ifelse(leads$Next == "-", "", leads$Next), Species = leads$Taxon, Photo = photoCell,
    check.names = FALSE, stringsAsFactors = FALSE
  )
  # Remarks (pruneKey() writes them) and lead labels, when the key has any
  kept <- c("Statement", "Choice", "Character", "Next", "Taxon", "Question", "Image", "Prev")
  for (col in c("Note", "Label")) {
    x <- if (is.null(raw[[col]])) "" else as.character(raw[[col]])
    x[is.na(x)] <- ""
    if (any(nzchar(trimws(x)))) {
      sheet[[col]] <- trimws(x)
      kept <- c(kept, col)
    }
  }
  # Every cell in quotes, so commas, quotes and line breaks inside one are
  # safe; line breaks are written as "\n", which is how they are read back
  cell <- function(x) {
    x <- gsub("\r\n?", "\n", enc2utf8(x))
    paste0("\"", gsub("\"", "\"\"", x, fixed = TRUE), "\"")
  }
  lines <- c(paste(cell(names(sheet)), collapse = ","), do.call(paste, c(lapply(sheet, cell), sep = ",")))
  if (isTRUE(bom)) lines[1] <- paste0("\ufeff", lines[1])
  dir.create(dirname(file), showWarnings = FALSE, recursive = TRUE)
  con <- base::file(file, "wb")
  on.exit(close(con))
  writeLines(enc2utf8(lines), con, sep = "\n", useBytes = TRUE)

  extra <- setdiff(names(raw), kept)
  extra <- extra[vapply(extra, function(col) any(!is.na(raw[[col]]) & nzchar(as.character(raw[[col]]))), logical(1))]
  if (length(extra)) {
    message("Not written to the spreadsheet: the leads' ", paste(extra, collapse = ", "), " column",
            if (length(extra) == 1) "" else "s")
  }
  invisible(file)
}

# Write an embedded photo (a data URI) into `folder` and return its file
# name: the id with the image type's extension, so that reading the sheet
# back gives the same id. Characters that cannot be in a file name, or that
# separate the names in a Photo cell, become "_". A name that is taken by
# another photo of the key (in any capitals: Windows and macOS do not tell
# "Leaf.jpg" from "leaf.jpg") gets a number. A different file of that name
# already in the folder is kept.
qualPhotoFile <- function(id, uri, folder, taken = character()) {
  mime <- sub("^data:([^;,]*).*$", "\\1", uri)
  ext <- switch(mime, "image/jpeg" = "jpg", "image/svg+xml" = "svg", gsub("[^A-Za-z0-9]", "", sub("^image/", "", mime)))
  if (!nzchar(ext)) ext <- "img"
  stem <- gsub("[/\\\\:*?\"<>|,;[:cntrl:]]+", "_", id)
  stem <- sub("^[. ]+", "", sub("[. ]+$", "", stem))
  if (!nzchar(stem)) stem <- "photo"
  name <- paste0(stem, ".", ext)
  n <- 1
  while (tolower(name) %in% tolower(taken)) {
    n <- n + 1
    name <- paste0(stem, "_", n, ".", ext)
  }
  bytes <- base64enc::base64decode(sub("^data:[^,]*,", "", uri))
  dir.create(folder, showWarnings = FALSE, recursive = TRUE)
  path <- file.path(folder, name)
  if (file.exists(path)) {
    same <- file.size(path) == length(bytes) && identical(readBin(path, "raw", length(bytes)), bytes)
    if (!same) message("Kept the ", name, " already in ", folder, " rather than replace it with the key's copy")
    return(name)
  }
  writeBin(bytes, path)
  name
}

# Letters for the leads of a couplet with `n` leads: a to z, then aa, ab, ...
qualChoiceLetters <- function(n) {
  out <- letters
  last <- letters
  while (length(out) < n) {
    last <- paste0(rep(last, each = 26), letters)
    out <- c(out, last)
  }
  out
}

# ---- R/quality.R ------------------------------------------------------------
#' How quickly a key gets to a result
#'
#' Counts the steps (couplets answered) it takes to reach each result of a
#' key and compares the average with the fewest steps any key could need.
#'
#' A key is a code: each result is spelled by the leads chosen on the way to
#' it. `bound` is the expected number of steps of the best key there could
#' be for the same taxa and the same `weights`, among keys whose couplets
#' have no more leads than the largest couplet of this key (`maxLeads`). It
#' is found by Huffman's construction, which joins the rarest taxa first, so
#' it is a number of steps that a key can really reach: 3 for eight equally
#' common taxa and couplets of two leads, about 3.55 for eleven. No key can
#' do better, however its characters are chosen. `efficiency` is
#' `bound / expectedSteps`: 1 for a key that could not be shorter, and lower
#' the more steps the key takes than it would have to. Real keys rarely
#' reach 1, because the characters that would split the taxa evenly may not
#' exist.
#'
#' When some taxa are met more often than others (`weights`), a good key
#' asks few questions before reaching the common ones, and the bound takes
#' the weights into account in the same way.
#'
#' In a key that has a few large couplets among many small ones (a
#' PhyloTree key has couplets of 2 and of 87 leads), the best key is allowed
#' the largest couplet everywhere, so the bound is far below what the key
#' does and `efficiency` is low. Three more numbers describe such keys
#' without that comparison. `entropy` is the Shannon entropy of the weights
#' in bits (`log2` of the number of taxa when they are equally common): the
#' information a key has to gather. A couplet with `k` leads can give up to
#' `log2(k)` bits, and `bitsPerStep` is the average of that over the steps
#' this key takes (1 for a key of two-lead couplets). `capacityUsed` is
#' `entropy / (bitsPerStep * expectedSteps)`: the share of the information
#' its couplets could give that the key needs. It is 1 when every couplet
#' splits what reaches it evenly, whatever its size, and it is not a
#' comparison with a shorter key.
#'
#' Two cases need a rule:
#'
#' * A taxon that keys out at several terminal leads counts once: its steps
#'   are the mean over its leads, as if its specimens were split evenly
#'   among them, and its weight is not multiplied by the number of leads.
#' * A couplet reached from several leads (a reticulate key) is counted by
#'   its shortest route from the first couplet, so `steps` is the fewest
#'   steps in which a result can be reached. `depth` is the longest route.
#'
#' Leads in couplets that cannot be reached from the first couplet, and
#' terminal leads that name no taxon, are left out of the averages.
#'
#' @param key A [dimoose] key.
#' @param weights How common each taxon is: a numeric vector whose names
#'   are the key's results as written in its `Taxon` column, such as the
#'   output of [occurrenceWeights()]. They need not sum to 1, and names
#'   that are not in the key are ignored. Taxa that are missing from it or
#'   `NA` count as 0, with a warning. A vector without names is an error,
#'   as is a name that is there twice. `NULL` (the default) treats all taxa
#'   as equally common.
#' @return A list with
#'   * `taxa`: a data frame with one row per taxon: `Taxon`, `leads` (how
#'     many terminal leads end in it), `steps` (mean over those leads),
#'     `minSteps`, `maxSteps` and `weight` (its share of the weights, summing
#'     to 1);
#'   * `leads`: a data frame with one row per terminal lead: `Lead` (its
#'     label, e.g. `"7b"`), `Statement`, `Choice`, `Taxon` and `steps`;
#'   * `meanLeadSteps`: mean steps over terminal leads;
#'   * `meanTaxonSteps`: mean steps over taxa;
#'   * `expectedSteps`: mean steps over taxa weighted by `weight` (the same
#'     as `meanTaxonSteps` without `weights`);
#'   * `bound`: the expected steps of the best possible key to these taxa
#'     with these weights and couplets of at most `maxLeads` leads;
#'   * `efficiency`: `bound / expectedSteps`, above 0 and at most 1 (`NA`
#'     for a key to a single taxon, which needs no steps);
#'   * `entropy`: the Shannon entropy of `weight`, in bits;
#'   * `bitsPerStep`: the most a step of this key can tell, on average
#'     (1 when every couplet has two leads);
#'   * `capacityUsed`: `entropy / (bitsPerStep * expectedSteps)`, at most 1;
#'   * `maxLeads`: the number of leads in the key's largest couplet;
#'   * `depth`: the longest route to a result, in steps.
#' @seealso `summary()` on a key, which reports the aggregates;
#'   [occurrenceWeights()] for weights from GBIF.
#' @examples
#' q <- keyQuality(arachnidaKey())
#' q$taxa
#' q$expectedSteps
#' q$bound
#' q$efficiency
#'
#' # spiders and mites are met far more often than the other orders
#' common <- c(Araneae = 50, Acari = 40, Opiliones = 5, Scorpiones = 3)
#' suppressWarnings(keyQuality(arachnidaKey(), common))$expectedSteps
#' @export
keyQuality <- function(key, weights = NULL) {
  if (!inherits(key, "dimoose")) stop("`key` must be a dimoose object", call. = FALSE)
  leads <- normalizeLeads(key$leads)
  check <- checkLeads(leads)
  depths <- qualCoupletDepths(leads, check)
  label <- leadLabels(leads)

  at <- match(leads$Statement, check$couplets)
  terminal <- which(leads$Next == "-" & !is.na(depths$shortest[at]))
  leadTable <- data.frame(
    Lead = label[terminal], Statement = leads$Statement[terminal], Choice = leads$Choice[terminal],
    Taxon = leads$Taxon[terminal], steps = depths$shortest[at[terminal]] + 1,
    stringsAsFactors = FALSE
  )
  named <- leadTable[nzchar(leadTable$Taxon), , drop = FALSE]
  taxon <- unique(named$Taxon)
  byTaxon <- split(named$steps, factor(named$Taxon, levels = taxon))
  taxa <- data.frame(
    Taxon = taxon,
    leads = as.integer(lengths(byTaxon)),
    steps = vapply(byTaxon, mean, 0),
    minSteps = vapply(byTaxon, min, 0),
    maxSteps = vapply(byTaxon, max, 0),
    stringsAsFactors = FALSE
  )
  taxa$weight <- qualWeights(taxon, weights)
  rownames(taxa) <- NULL

  size <- as.numeric(table(factor(leads$Statement, levels = check$couplets)))
  reached <- !is.na(depths$shortest)
  maxLeads <- if (any(reached)) as.integer(max(size[reached])) else 0L
  none <- nrow(taxa) == 0
  expected <- if (none) NA_real_ else sum(taxa$weight * taxa$steps)
  p <- taxa$weight[taxa$weight > 0]
  entropy <- if (none) NA_real_ else -sum(p * log2(p))
  # The chance of coming through each couplet, with a taxon's weight split
  # evenly among its leads; the bits its leads could tell apart are log2(size)
  bitsPerStep <- NA_real_
  if (!none) {
    share <- taxa$weight[match(named$Taxon, taxon)] / taxa$leads[match(named$Taxon, taxon)]
    visit <- qualVisitProbability(match(named$Statement, check$couplets), share, depths)
    bitsPerStep <- sum(visit * log2(pmax(size, 1))) / sum(visit)
  }
  bound <- if (none) NA_real_ else qualOptimalSteps(taxa$weight, maxLeads)
  capacity <- if (none || !isTRUE(bitsPerStep > 0)) NA_real_ else min(1, entropy / (bitsPerStep * expected))
  list(
    taxa = taxa,
    leads = leadTable,
    meanLeadSteps = if (nrow(named)) mean(named$steps) else NA_real_,
    meanTaxonSteps = if (none) NA_real_ else mean(taxa$steps),
    expectedSteps = expected,
    bound = bound,
    efficiency = if (is.na(bound) || bound <= 0) NA_real_ else min(1, bound / expected),
    entropy = entropy,
    bitsPerStep = bitsPerStep,
    capacityUsed = capacity,
    maxLeads = maxLeads,
    depth = if (length(terminal)) as.integer(max(depths$longest[at[terminal]]) + 1) else 0L
  )
}

# The expected steps of the best key to taxa with probabilities `p` whose
# couplets have at most `arity` leads: Huffman's construction, which joins
# the `arity` least likely groups into one couplet until one group is left.
# Each joining adds a step for everything in the new group, so the expected
# steps are the sum of the joined groups' probabilities. Groups of
# probability 0 are added first so that the last couplet made (the first
# one asked) is a full one.
qualOptimalSteps <- function(p, arity) {
  n <- length(p)
  if (n <= 1) return(0)
  arity <- max(2, arity)
  if (arity >= n) return(sum(p))
  pad <- (arity - 1 - (n - 1) %% (arity - 1)) %% (arity - 1)
  leaf <- c(rep(0, pad), sort(p))
  joins <- (length(leaf) - 1) / (arity - 1)
  # `leaf` and the groups made so far (`node`) are both in rising order, so
  # the least likely group is always at the front of one of the two
  node <- numeric(joins)
  i <- 1
  j <- 1
  steps <- 0
  for (made in seq_len(joins)) {
    total <- 0
    for (pick in seq_len(arity)) {
      if (j >= made || (i <= length(leaf) && leaf[i] <= node[j])) {
        total <- total + leaf[i]
        i <- i + 1
      } else {
        total <- total + node[j]
        j <- j + 1
      }
    }
    node[made] <- total
    steps <- steps + total
  }
  steps
}

# The probability of coming through each couplet on the way to a result,
# given the probability `share` of ending at a lead of couplet `at`. Each
# couplet passes its probability up to the couplet it is first reached from.
qualVisitProbability <- function(at, share, depths) {
  visit <- numeric(length(depths$shortest))
  own <- tapply(share, at, sum)
  visit[as.integer(names(own))] <- own
  deepest <- suppressWarnings(max(depths$shortest, na.rm = TRUE))
  for (d in rev(seq_len(max(deepest, 0)))) {
    here <- which(depths$shortest == d)
    up <- tapply(visit[here], depths$parent[here], sum)
    visit[as.integer(names(up))] <- visit[as.integer(names(up))] + up
  }
  visit
}

# Steps from the root to each couplet (0 for the root, NA when it cannot be
# reached): `shortest` over all routes and `longest` over all routes, and the
# `parent` couplet on a shortest route. A key with a cycle has no longest
# route; `longest` is then the shortest.
qualCoupletDepths <- function(leads, check) {
  couplets <- check$couplets
  n <- length(couplets)
  shortest <- rep(NA_real_, n)
  parent <- rep(NA_integer_, n)
  if (n == 0) return(list(shortest = shortest, longest = shortest, parent = parent))
  from <- match(leads$Statement, couplets)
  to <- match(leads$Next, couplets)
  edge <- leads$Next != "-" & !is.na(to)
  from <- from[edge]
  to <- to[edge]

  root <- match(check$root, couplets)
  shortest[root] <- 0
  frontier <- root
  while (length(frontier)) {
    out <- which(from %in% frontier & is.na(shortest[to]))
    nxt <- unique(to[out])
    parent[nxt] <- from[out[match(nxt, to[out])]]
    shortest[nxt] <- shortest[frontier[1]] + 1
    frontier <- nxt
  }

  # Longest route: push each couplet's depth along its leads until nothing
  # changes. In a key without cycles that takes at most one pass per couplet.
  longest <- rep(NA_real_, n)
  longest[root] <- 0
  settled <- FALSE
  for (pass in seq_len(n + 1)) {
    reach <- longest[from] + 1
    known <- !is.na(reach) & to != root
    if (!any(known)) {
      settled <- TRUE
      break
    }
    best <- tapply(reach[known], to[known], max)
    target <- as.integer(names(best))
    better <- is.na(longest[target]) | best > longest[target]
    if (!any(better)) {
      settled <- TRUE
      break
    }
    longest[target[better]] <- best[better]
  }
  if (!settled) longest <- shortest
  list(shortest = shortest, longest = longest, parent = parent)
}

# Each taxon's share of the weights (summing to 1); equal shares without
# weights.
qualWeights <- function(taxon, weights) {
  n <- length(taxon)
  if (n == 0) return(numeric())
  if (is.null(weights)) return(rep(1 / n, n))
  if (!is.numeric(weights) || length(dim(weights)) > 1) {
    stop("`weights` must be a numeric vector named by the key's taxa", call. = FALSE)
  }
  if (is.null(names(weights))) {
    stop("`weights` must be a numeric vector named by the key's taxa; this one has no names", call. = FALSE)
  }
  names(weights) <- trimws(names(weights))
  twice <- unique(names(weights)[duplicated(names(weights)) & names(weights) %in% taxon])
  if (length(twice)) {
    stop("`weights` has more than one value for ", paste(utils::head(twice, 5), collapse = ", "),
         if (length(twice) > 5) ", ...", call. = FALSE)
  }
  w <- unname(weights[match(taxon, names(weights))])
  absent <- is.na(w)
  if (all(absent)) stop("None of the names of `weights` is a taxon of the key", call. = FALSE)
  if (any(absent)) {
    warning(sprintf("%d of the key's %d taxa have no weight and count as 0: %s", sum(absent), n,
                    paste(utils::head(taxon[absent], 5), collapse = ", ")),
            if (sum(absent) > 5) ", ...", call. = FALSE)
    w[absent] <- 0
  }
  if (any(w < 0) || any(!is.finite(w))) stop("`weights` must be finite and not negative", call. = FALSE)
  if (sum(w) <= 0) stop("`weights` are all 0 for the key's taxa", call. = FALSE)
  w / sum(w)
}

#' How common each taxon of a key is, from GBIF occurrence records
#'
#' Counts the occurrence records [GBIF](https://www.gbif.org) holds for each
#' result of a key, optionally within a country or region. The counts can be
#' given to [keyQuality()] or `summary()` as `weights`, to see how many
#' steps the key takes for the taxa people actually meet.
#'
#' A result written as `"Common name (Genus species)"` is looked up by the
#' name in parentheses; other results by the result itself when it looks
#' like a scientific name, which includes genera and families (`"Salix"`,
#' `"Salix sp."` and `"Salix spp."` all count the genus) and names followed
#' by their author (`"Puma concolor (Linnaeus, 1771)"`). A result that
#' lists several taxa the key does not separate, written `"A / B"` as
#' [keyFromRpart()] and [keyFromMatrix()] write them, gets the sum of their
#' counts. Each name is matched to the GBIF Backbone Taxonomy, and the
#' records of the name GBIF accepts for it are counted, so a synonym gets
#' the count of its accepted name. This makes two requests to GBIF per
#' name, one name at a time; after three failed requests in a row the rest
#' are not tried.
#'
#' A name that GBIF knows in more than one kingdom (`"Morus"` is a mulberry
#' and a gannet) is not counted unless `kingdom` says which is meant.
#'
#' Occurrence counts measure how often a taxon is recorded, which follows
#' how conspicuous and how popular with observers it is as well as how
#' common it is. A taxon with no records gets a weight of 0 and so does not
#' count towards the expected steps at all.
#'
#' @param key A [dimoose] key.
#' @param region Where to count: `NULL` for the whole world, a two-letter
#'   ISO country code (`"US"`), or a [GADM](https://gadm.org) id for a
#'   country, state or county (`"USA.27_1"` is Montana). Anything else is
#'   an error. GBIF answers 0 for a GADM id it does not have, so when no
#'   taxon has a record in the region a warning asks to check it.
#' @param source Where the counts come from; only `"gbif"` for now.
#' @param fetch The function that asks GBIF: called as `fetch(url, query)`
#'   with a named list of query parameters, it returns the parsed JSON
#'   answer as a list. Replace it to use cached answers or to test without
#'   a connection.
#' @param kingdom Optional kingdom ("Plantae", "Animalia", ...), which helps
#'   GBIF tell apart names that are used in more than one kingdom.
#' @return A numeric vector of record counts named by the key's results (as
#'   in its `Taxon` column), `NA` for results that have no scientific name,
#'   that GBIF does not know or cannot tell apart, or whose request failed
#'   (each with a warning).
#' @seealso [keyQuality()], [checkNames()]
#' @examples
#' # canned answers in place of GBIF, to show the shape of `fetch`
#' counts <- c("Acer negundo" = 61000, "Fraxinus pennsylvanica" = 48000)
#' canned <- function(url, query) {
#'   if (grepl("species/match", url)) {
#'     list(usageKey = match(query$name, names(counts)), matchType = "EXACT")
#'   } else {
#'     list(count = unname(counts[query$taxonKey]))
#'   }
#' }
#' leads <- data.frame(
#'   Statement = "1", Choice = c("a", "b"), Character = c("Leaflets 3.", "Leaflets 5 to 7."),
#'   Next = "-", Taxon = c("Box elder (Acer negundo)", "Green ash (Fraxinus pennsylvanica)")
#' )
#' occurrenceWeights(keyFromLeads(leads), fetch = canned)
#' \donttest{
#' k <- montanaKey()
#' w <- occurrenceWeights(k, region = "USA.27_1", kingdom = "Plantae")
#' w
#' summary(k, weights = w)
#' }
#' @export
occurrenceWeights <- function(key, region = NULL, source = "gbif", fetch = qualGbifFetch, kingdom = NULL) {
  if (!inherits(key, "dimoose")) stop("`key` must be a dimoose object", call. = FALSE)
  source <- match.arg(source, "gbif")
  if (!is.function(fetch)) stop("`fetch` must be a function of a URL and a list of query parameters", call. = FALSE)
  where <- qualRegionQuery(region)
  leads <- normalizeLeads(key$leads)
  taxa <- unique(leads$Taxon[leads$Next == "-" & nzchar(leads$Taxon)])
  # a result may list several taxa ("A / B"); it gets the sum of their counts
  parts <- lapply(strsplit(taxa, " / ", fixed = TRUE), function(x) qualLookupName(trimws(x)))

  # one answer per name: its count, or NA and why
  count <- numeric()
  why <- character()
  failure <- character()
  inARow <- 0
  for (name in unique(stats::na.omit(unlist(parts)))) {
    if (inARow >= 3) {
      count[name] <- NA_real_
      why[name] <- "not tried"
      next
    }
    res <- tryCatch({
      m <- fetch("https://api.gbif.org/v1/species/match", qualDropNull(list(name = name, kingdom = kingdom)))
      type <- if (is.null(m$matchType)) "NONE" else m$matchType
      taxonKey <- if (!is.null(m$acceptedUsageKey)) m$acceptedUsageKey else m$usageKey
      # GBIF calls a genus that also has a species-rank entry of the same
      # name a HIGHERRANK match; it is the genus asked for all the same
      itself <- !is.null(m$canonicalName) && identical(tolower(m$canonicalName), tolower(name))
      if (type == "NONE" && !is.null(m$note) && grepl("Multiple equal matches", m$note, fixed = TRUE)) {
        list(count = NA_real_, why = "ambiguous")
      } else if (type == "NONE" || (type == "HIGHERRANK" && !itself) || is.null(taxonKey)) {
        list(count = NA_real_, why = "unknown")
      } else {
        found <- fetch("https://api.gbif.org/v1/occurrence/search", c(list(taxonKey = taxonKey, limit = 0), where))
        if (is.null(found$count)) stop("GBIF's answer for ", name, " has no count")
        list(count = as.numeric(found$count), why = "")
      }
    }, error = function(e) {
      failure <<- c(failure, conditionMessage(e))
      list(count = NA_real_, why = "failed")
    })
    inARow <- if (res$why == "failed") inARow + 1 else 0
    count[name] <- res$count
    why[name] <- res$why
  }
  counts <- vapply(parts, function(x) if (anyNA(x)) NA_real_ else sum(count[x]), numeric(1))
  names(counts) <- taxa

  some <- function(x) paste0(paste(utils::head(x, 5), collapse = ", "), if (length(x) > 5) ", ..." else "")
  noName <- taxa[vapply(parts, anyNA, logical(1))]
  if (length(noName)) {
    warning(sprintf("%d result%s without a scientific name not counted: %s", length(noName),
                    if (length(noName) == 1) "" else "s", some(noName)), call. = FALSE)
  }
  unknown <- names(why)[why == "unknown"]
  if (length(unknown)) warning("Not in GBIF, so not counted: ", some(unknown), call. = FALSE)
  ambiguous <- names(why)[why == "ambiguous"]
  if (length(ambiguous)) {
    warning("GBIF knows more than one taxon by this name, so not counted (say which with `kingdom`): ",
            some(ambiguous), call. = FALSE)
  }
  failed <- sum(why %in% c("failed", "not tried"))
  if (failed) {
    warning(sprintf("Could not get the count of %d name%s from GBIF: %s", failed, if (failed == 1) "" else "s", failure[1]),
            if (any(why == "not tried")) "; gave up after 3 failed requests in a row", call. = FALSE)
  }
  if (length(where) && any(!is.na(counts)) && all(counts[!is.na(counts)] == 0)) {
    warning("GBIF has no records of these taxa in ", where[[1]], "; check that it is the region meant", call. = FALSE)
  }
  counts
}

# The name to look a result up by, or NA when it has none: the name in
# parentheses of "Common name (Genus species)", otherwise the result itself
# when it looks like a scientific name. Parentheses that hold an author
# ("Puma concolor (Linnaeus, 1771)") are dropped, and "Salix sp." or
# "Salix spp." is the genus.
qualLookupName <- function(taxa) {
  genus <- function(x) trimws(sub("\\s+spp?\\.?$", "", x))
  inside <- genus(scientificPart(taxa))
  # an author: the name is what stands before the parentheses
  author <- !is.na(inside) & grepl("[0-9]{4}|,|&|\\.$", inside)
  inside[author] <- NA_character_
  taxa[author] <- sub("\\s*\\([^()]*\\)$", "", taxa[author])
  name <- ifelse(is.na(inside), genus(taxa), inside)
  name[!nzchar(name)] <- NA_character_
  ok <- !is.na(name)
  ok[ok] <- isScientificName(name[ok])
  name[!ok] <- NA_character_
  name
}

# The occurrence search parameter for a region: `country` for a two-letter
# code, `gadmGid` for a GADM id (three letters, then numbered levels).
qualRegionQuery <- function(region) {
  if (is.null(region)) return(list())
  if (!is.character(region) || length(region) != 1 || is.na(region) || !nzchar(trimws(region))) {
    stop("`region` must be one country code or GADM id", call. = FALSE)
  }
  region <- toupper(trimws(region))
  if (grepl("^[A-Z]{2}$", region)) return(list(country = region))
  if (!grepl("^[A-Z]{3}(\\.[0-9]+)*(_[0-9]+)?$", region)) {
    stop("`region` must be a two-letter country code (\"US\") or a GADM id (\"USA.27_1\"), not ", region, call. = FALSE)
  }
  list(gadmGid = region)
}

qualDropNull <- function(x) x[!vapply(x, is.null, logical(1))]

# Ask the GBIF API (https://techdocs.gbif.org/en/openapi/) and parse its JSON.
qualGbifFetch <- function(url, query) {
  r <- httr::GET(url, query = query, dimooseUserAgent(), httr::timeout(30))
  httr::stop_for_status(r, task = "ask GBIF")
  httr::content(r, as = "parsed", type = "application/json", encoding = "UTF-8")
}

# ---- the page's entry point ----
webrWizard <- function(csv, out, title = NA) {
  notes <- character()
  withCallingHandlers({
    key <- keyFromSpreadsheet(csv, desc = title)
    notes <- c(notes, key$validate())
    exportWizard(key, out)
  }, warning = function(w) {
    notes <<- c(notes, conditionMessage(w))
    invokeRestart("muffleWarning")
  })
  leads <- key$leads
  photos <- sum(grepl("^image_", key$meta$key))
  paste(c(
    paste("couplets:", length(unique(leads$Statement))),
    paste("results:", length(unique(leads$Taxon[nzchar(leads$Taxon)]))),
    paste("photos:", photos),
    if (length(notes)) paste("note:", unique(gsub("\n", " ", notes)))
  ), collapse = "\n")
}
